def alert_sensors(readings, max_temp):
    flagged = []
    for sensor_id, temp, humidity in readings:
        if temp > max_temp:
            flagged.append(sensor_id)
    return tuple(flagged)

def total_playlist_time(tracks):
    total_sec = 0
    for _, mins, secs in tracks:
        total_sec += mins * 60 + secs
    return (total_sec // 60, total_sec % 60)

def format_shelf_labels(locations):
    labels = []
    for aisle, bay, shelf in locations:
        labels.append(f"{aisle}-{bay}-{shelf}")
    return labels

def cheapest_seat(tickets):
    best = min(tickets, key=lambda x: x[2])
    return (best[0], best[1])

def zip_code_weight(packages, target_zip):
    total = 0
    for _, zip_code, weight in packages:
        if zip_code == target_zip:
            total += weight
    return total

def flag_low_stock(inventory):
    updated = []
    for name, stock, limit in inventory:
        updated.append((name, stock, limit, stock < limit))
    return updated

def combine_menu_info(prices, nutrition):
    combined = []
    for (dish, price), (_, calories) in zip(prices, nutrition):
        combined.append((dish, price, calories))
    return combined

def count_visitors_at_hour(logs, target_hour):
    count = 0
    for _, entry, exit_hr in logs:
        if entry <= target_hour < exit_hr:
            count += 1
    return count

def max_playlist_tracks(track_lengths, limit):
    total = 0
    count = 0
    for length in sorted(track_lengths):
        if total + length <= limit:
            total += length
            count += 1
        else:
            break
    return count

def min_shelf_boxes(capacities, total_weight):
    used = 0
    for cap in sorted(capacities, reverse=True):
        if total_weight <= 0:
            break
        total_weight -= cap
        used += 1
    return used if total_weight <= 0 else -1

def count_sensor_segments(readings, max_span):
    if not readings:
        return 0
    segments = 1
    start = readings[0]
    for r in readings:
        if r - start > max_span:
            segments += 1
            start = r
    return segments

def match_audio_kits(group_sizes, kit_capacities):
    groups = sorted(group_sizes)
    kits = sorted(kit_capacities)
    g = 0
    for k in kits:
        if g < len(groups) and k >= groups[g]:
            g += 1
    return g

def max_loyalty_rebate(spend, vouchers):
    rebate = 0
    for value, min_spend in sorted(vouchers, reverse=True):
        if spend >= min_spend:
            rebate += value
            spend -= min_spend
    return rebate

def count_accepted_bookings(bookings):
    count = 0
    last_end = -1
    for start, end in sorted(bookings, key=lambda x: x[1]):
        if start >= last_end:
            count += 1
            last_end = end
    return count

def count_shelf_labels(words, max_width):
    if not words:
        return 0
    labels = 1
    current = len(words[0])
    for w in words[1:]:
        if current + 1 + len(w) <= max_width:
            current += 1 + len(w)
        else:
            labels += 1
            current = len(w)
    return labels

def count_kayak_boats(weights, limit):
    w = sorted(weights)
    left, right = 0, len(w) - 1
    boats = 0
    while left <= right:
        if w[left] + w[right] <= limit:
            left += 1
        right -= 1
        boats += 1
    return boats

def max_coffee_profit(batches, k):
    margins = sorted((price - cost for price, cost in batches), reverse=True)
    total = 0
    for m in margins[:k]:
        if m > 0:
            total += m
    return total

def first_song_reaching_target(durations, target):
    total = 0
    for i, d in enumerate(durations):
        total += d
        if total >= target:
            return i
    return -1

def query_rainfall_ranges(daily_rain, queries):
    prefix = [0]
    for r in daily_rain:
        prefix.append(prefix[-1] + r)
    return [prefix[end + 1] - prefix[start] for start, end in queries]

def count_deficit_stops(net_crates):
    balance = 0
    deficits = 0
    for c in net_crates:
        balance += c
        if balance < 0:
            deficits += 1
    return deficits

def highest_drone_elevation(base_altitude, changes):
    current = base_altitude
    highest = base_altitude
    for delta in changes:
        current += delta
        if current > highest:
            highest = current
    return highest

def track_remaining_budget(initial_budget, expenses):
    remaining = initial_budget
    history = []
    for cost in expenses:
        if remaining - cost < 0:
            break
        remaining -= cost
        history.append(remaining)
    return history

def empty_aisles(seat_map):
    if not seat_map or not seat_map[0]:
        return []
    num_cols = len(seat_map[0])
    result = []
    for col in range(num_cols):
        if all(row[col] == 0 for row in seat_map):
            result.append(col)
    return result

def border_sensor_average(grid):
    rows, cols = len(grid), len(grid[0])
    total = 0
    count = 0
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                total += grid[r][c]
                count += 1
    return total / count

def heaviest_shelf(shelves):
    best_idx = 0
    max_weight = sum(shelves[0])
    for idx, row in enumerate(shelves):
        current = sum(row)
        if current > max_weight:
            max_weight = current
            best_idx = idx
    return (best_idx, max_weight)

def count_moisture_peaks(farm):
    peaks = 0
    for row in farm:
        for c in range(1, len(row) - 1):
            if row[c] > row[c - 1] and row[c] > row[c + 1]:
                peaks += 1
    return peaks

def swap_tile_quadrants(tile):
    n = len(tile)
    half = n // 2
    res = [row[:] for row in tile]
    for r in range(half):
        for c in range(half):
            res[r][c], res[r + half][c + half] = res[r + half][c + half], res[r][c]
    return res

def serpent_badge_codes(grid):
    codes = []
    for r, row in enumerate(grid):
        if r % 2 == 0:
            codes.extend(row)
        else:
            codes.extend(row[::-1])
    return codes

def apply_parking_reservations(lot, bookings):
    newly_reserved = 0
    for r, c in bookings:
        if lot[r][c] == 0:
            lot[r][c] = 1
            newly_reserved += 1
    return newly_reserved

def has_matching_diagonals(pattern):
    n = len(pattern)
    for i in range(n):
        if pattern[i][i] != pattern[i][n - 1 - i]:
            return False
    return True

def merge_billboard_columns(grid):
    compressed = []
    for row in grid:
        new_row = [row[i] + row[i + 1] for i in range(0, len(row), 2)]
        compressed.append(new_row)
    return compressed

def adjacent_mineral_yield(grid, row, col):
    rows, cols = len(grid), len(grid[0])
    total = 0
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = row + dr, col + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            total += grid[nr][nc]
    return total

def find_full_rows(seat_grid):
    full_rows = []
    for idx, row in enumerate(seat_grid):
        if row and all(seat == 1 for seat in row):
            full_rows.append(idx)
    return full_rows

def sum_interior_readings(grid):
    if len(grid) <= 2 or len(grid[0]) <= 2:
        return 0
    total = 0
    for r in range(1, len(grid) - 1):
        for c in range(1, len(grid[0]) - 1):
            total += grid[r][c]
    return total

def max_stack_weights(warehouse):
    if not warehouse or not warehouse[0]:
        return []
    num_cols = len(warehouse[0])
    return [max(warehouse[r][c] for r in range(len(warehouse))) for c in range(num_cols)]

def count_shelves_with_tag(shelves, tag):
    count = 0
    for shelf in shelves:
        if tag in shelf:
            count += 1
    return count

def adjust_brightness(image, offset):
    result = []
    for row in image:
        new_row = [max(0, min(255, pixel + offset)) for pixel in row]
        result.append(new_row)
    return result

def find_dry_plots(moisture_grid, threshold):
    coords = []
    for r in range(len(moisture_grid)):
        for c in range(len(moisture_grid[r])):
            if moisture_grid[r][c] < threshold:
                coords.append((r, c))
    return coords

def swap_aisles(layout, col1, col2):
    for row in layout:
        row[col1], row[col2] = row[col2], row[col1]
    return layout

def is_valid_checkerboard(board):
    n = len(board)
    for r in range(n):
        for c in range(n):
            if r > 0 and board[r][c] == board[r - 1][c]:
                return False
            if c > 0 and board[r][c] == board[r][c - 1]:
                return False
    return True

def diagonal_solar_output(grid):
    n = len(grid)
    total = 0
    for i in range(n):
        total += grid[i][i]
        if i != n - 1 - i:
            total += grid[i][n - 1 - i]
    return total

def build_seating_chart(guests, rows, cols):
    chart = []
    for r in range(rows):
        row = []
        for c in range(cols):
            idx = r * cols + c
            row.append(guests[idx] if idx < len(guests) else 'Empty')
        chart.append(row)
    return chart

def find_low_stock_items(inventory, threshold):
    low_stock = []
    for name, aisle, quantity in inventory:
        if quantity < threshold:
            low_stock.append(name)
    return tuple(low_stock)

def widest_temp_range_sensor(readings):
    best_sensor = readings[0][0]
    max_span = readings[0][2] - readings[0][1]
    for sensor_id, min_t, max_t in readings[1:]:
        span = max_t - min_t
        if span > max_span:
            max_span = span
            best_sensor = sensor_id
    return best_sensor

def reroute_shipping_label(label):
    sender, origin, dest, recipient = label
    return (sender, dest, origin, recipient)

def available_window_seats(seats):
    available = []
    for coach, row, letter, is_booked in seats:
        if not is_booked and letter in ('A', 'F'):
            available.append((coach, row, letter))
    return available

def merge_vital_logs(log1, log2):
    combined = log1 + log2
    return sorted(combined, key=lambda record: record[0])

def update_menu_price(menu, target_dish, new_price):
    updated = []
    for dish, category, price in menu:
        if dish == target_dish:
            updated.append((dish, category, new_price))
        else:
            updated.append((dish, category, price))
    return tuple(updated)

def summarize_checkouts(checkouts):
    summary = {}
    for member_id, title, days in checkouts:
        count, total_days = summary.get(member_id, (0, 0))
        summary[member_id] = (count + 1, total_days + days)
    return summary

def net_ledger_change(transactions):
    balance = 0
    for tx_id, tx_type, amount in transactions:
        if tx_type == 'credit':
            balance += amount
        elif tx_type == 'debit':
            balance -= amount
    return balance

def podium_runners(results):
    sorted_results = sorted(results, key=lambda r: r[2])
    top_three = [r[0] for r in sorted_results[:3]]
    return tuple(top_three)

def filter_sensor_spikes(readings, threshold):
    result = []
    for i in range(1, len(readings)):
        if abs(readings[i] - readings[i - 1]) >= threshold:
            result.append(readings[i])
    return result

def count_playable_songs(durations, limit):
    total = 0
    count = 0
    for d in durations:
        if total + d <= limit:
            total += d
            count += 1
        else:
            break
    return count

def get_aisles_for_bin(labels, target_bin):
    aisles = []
    for label in labels:
        parts = label.split('-')
        if int(parts[3]) == target_bin:
            aisles.append(int(parts[1]))
    return aisles

def find_isolated_seats(row):
    isolated = []
    for i in range(1, len(row) - 1):
        if row[i - 1] == 0 and row[i] == 0 and row[i + 1] == 0:
            isolated.append(i)
    return isolated

def combine_weekly_parcels(route_a, route_b):
    combined = []
    for i in range(len(route_a)):
        if i % 7 < 5:
            combined.append(max(route_a[i], route_b[i]))
        else:
            combined.append(route_a[i] + route_b[i])
    return combined

def total_ascent(elevations):
    gain = 0
    for i in range(1, len(elevations)):
        if elevations[i] > elevations[i - 1]:
            gain += elevations[i] - elevations[i - 1]
    return gain

def repair_battery_log(levels):
    fixed = list(levels)
    for i in range(1, len(levels) - 1):
        if levels[i] < 0:
            fixed[i] = (levels[i - 1] + levels[i + 1]) // 2
    return fixed

def group_full_days(temps):
    days = []
    for i in range(0, len(temps) - 23, 24):
        days.append(temps[i:i + 24])
    return days

def apply_third_item_discount(prices):
    result = []
    for i, price in enumerate(prices):
        if (i + 1) % 3 == 0:
            result.append(price / 2)
        else:
            result.append(price)
    return result

def first_overweight_box(weights, limit):
    running_weight = 0
    for i, w in enumerate(weights):
        running_weight += w
        if running_weight > limit:
            return i
    return -1

def count_low_altitude_days(changes, threshold):
    altitude = 0
    days = 0
    for change in changes:
        altitude += change
        if altitude < threshold:
            days += 1
    return days

def query_ticket_sales(daily_sales, queries):
    prefix = [0]
    for s in daily_sales:
        prefix.append(prefix[-1] + s)
    return [prefix[j + 1] - prefix[i] for i, j in queries]

def peak_bus_occupancy(stop_changes):
    current = 0
    peak = 0
    for change in stop_changes:
        current += change
        if current > peak:
            peak = current
    return peak

def split_bookshelf_index(widths):
    total = sum(widths)
    left_sum = 0
    for i, w in enumerate(widths):
        left_sum += w
        if left_sum == total - left_sum:
            return i
    return -1

def cumulative_loyalty_points(visit_points):
    history = []
    total = 0
    for pts in visit_points:
        total += pts
        if total >= 50:
            total += 10
        history.append(total)
    return history

def count_parcel_shipments(weights, limit):
    left, right = 0, len(weights) - 1
    shipments = 0
    while left <= right:
        if weights[left] + weights[right] <= limit:
            left += 1
        right -= 1
        shipments += 1
    return shipments

def count_shared_tickets(booth_a, booth_b):
    i, j = 0, 0
    shared = 0
    while i < len(booth_a) and j < len(booth_b):
        if booth_a[i] == booth_b[j]:
            shared += 1
            i += 1
            j += 1
        elif booth_a[i] < booth_b[j]:
            i += 1
        else:
            j += 1
    return shared

def verify_beacon_route(plan, log):
    p_idx, l_idx = 0, 0
    while p_idx < len(plan) and l_idx < len(log):
        if plan[p_idx] == log[l_idx]:
            p_idx += 1
        l_idx += 1
    return p_idx == len(plan)

def deduplicate_shelf_labels(labels):
    if not labels:
        return []
    write_idx = 0
    for read_idx in range(1, len(labels)):
        if labels[read_idx] != labels[write_idx]:
            write_idx += 1
            labels[write_idx] = labels[read_idx]
    return labels[:write_idx + 1]

def match_kayak_paddlers(paddlers, kayaks):
    p_idx, k_idx = 0, 0
    matched = 0
    while p_idx < len(paddlers) and k_idx < len(kayaks):
        if kayaks[k_idx] >= paddlers[p_idx]:
            matched += 1
            p_idx += 1
        k_idx += 1
    return matched

def find_gift_card_pair(prices, balance):
    left, right = 0, len(prices) - 1
    while left < right:
        total = prices[left] + prices[right]
        if total == balance:
            return (prices[left], prices[right])
        elif total < balance:
            left += 1
        else:
            right -= 1
    return None

def merge_sensor_logs(log_a, log_b):
    i, j = 0, 0
    merged = []
    while i < len(log_a) and j < len(log_b):
        if log_a[i] <= log_b[j]:
            merged.append(log_a[i])
            i += 1
        else:
            merged.append(log_b[j])
            j += 1
    return merged + log_a[i:] + log_b[j:]

def count_kayaks(weights, limit):
    left, right = 0, len(weights) - 1
    kayaks = 0
    while left <= right:
        if weights[left] + weights[right] <= limit:
            left += 1
        right -= 1
        kayaks += 1
    return kayaks

def match_invoices(invoices, payments, tolerance):
    i, j, matched = 0, 0, 0
    while i < len(invoices) and j < len(payments):
        if abs(invoices[i] - payments[j]) <= tolerance:
            matched += 1
            i += 1
            j += 1
        elif invoices[i] < payments[j] - tolerance:
            i += 1
        else:
            j += 1
    return matched

def alternate_readings(readings):
    left, right = 0, len(readings) - 1
    result = []
    while left <= right:
        result.append(readings[left])
        if left < right:
            result.append(readings[right])
        left += 1
        right -= 1
    return result

def verify_checkpoints(checkpoints, trail_log):
    i, j = 0, 0
    while i < len(checkpoints) and j < len(trail_log):
        if checkpoints[i] == trail_log[j]:
            i += 1
        j += 1
    return i == len(checkpoints)

def exclusive_badges(list1, list2):
    i, j, res = 0, 0, []
    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            res.append(list1[i])
            i += 1
        elif list1[i] > list2[j]:
            res.append(list2[j])
            j += 1
        else:
            i += 1
            j += 1
    return res + list1[i:] + list2[j:]

def compress_zones(zones):
    res, i, n = [], 0, len(zones)
    while i < n:
        j = i
        while j < n and zones[j] == zones[i]:
            j += 1
        res.append((zones[i], j - i))
        i = j
    return res

def count_unbalanced_pairs(weights, min_diff):
    left, count, n = 0, 0, len(weights)
    for right in range(n):
        while weights[right] - weights[left] >= min_diff:
            left += 1
        count += left
    return count

def smooth_sensor_readings(readings, threshold):
    if not readings:
        return []
    result = [readings[0]]
    for r in readings[1:]:
        if abs(r - result[-1]) > threshold:
            result.append(result[-1])
        else:
            result.append(r)
    return result

def get_aisle_shelves(labels, target_aisle):
    shelves = []
    for label in labels:
        aisle, shelf = label.split('-')
        if aisle == target_aisle:
            shelves.append(int(shelf))
    return shelves

def batch_packages(weights, max_capacity):
    if not weights:
        return []
    batches = [[]]
    current_weight = 0
    for w in weights:
        if current_weight + w <= max_capacity or not batches[-1]:
            batches[-1].append(w)
            current_weight += w
        else:
            batches.append([w])
            current_weight = w
    return batches

def calculate_altitude_gain(checkpoints):
    gain = 0
    for i in range(1, len(checkpoints)):
        diff = checkpoints[i] - checkpoints[i - 1]
        if diff > 0:
            gain += diff
    return gain

def merge_ticket_queues(regular, vip):
    merged = []
    r_idx, v_idx = 0, 0
    while r_idx < len(regular) or v_idx < len(vip):
        if v_idx < len(vip):
            merged.append(vip[v_idx])
            v_idx += 1
        for _ in range(2):
            if r_idx < len(regular):
                merged.append(regular[r_idx])
                r_idx += 1
    return merged

def apply_threshold_discount(prices, threshold, discount_pct):
    updated = []
    for p in prices:
        if p > threshold:
             discounted = round(p * (1 - discount_pct / 100.0), 2)
             updated.append(discounted)
        else:
             updated.append(round(p, 2))
    return updated

def window_temp_ranges(readings, k):
    ranges = []
    for i in range(0, len(readings) - k + 1, k):
        window = readings[i:i + k]
        ranges.append(max(window) - min(window))
    return ranges

def find_reorder_days(stock_levels, reorder_point):
    days = []
    for i in range(1, len(stock_levels)):
        if stock_levels[i - 1] >= reorder_point and stock_levels[i] < reorder_point:
            days.append(i)
    return days

def count_items_on_level(labels, target_level):
    count = 0
    for label in labels:
        parts = label.split('-')
        if int(parts[2]) == target_level:
            count += 1
    return count

def total_playlist_seconds(tracks):
    total = 0
    for track in tracks:
        minutes, seconds = track.split(':')
        total += int(minutes) * 60 + int(seconds)
    return total

def parse_sensor_readings(log_line):
    if not log_line:
        return {}
    readings = {}
    for entry in log_line.split(';'):
        sensor_id, temp = entry.split('=')
        readings[sensor_id] = float(temp)
    return readings

def seats_in_row(tickets, row_letter):
    seats = []
    for ticket in tickets:
        row, seat = ticket.split('#')
        if row == row_letter:
            seats.append(int(seat))
    return seats

def total_package_grams(tags):
    total = 0
    for tag in tags:
        weight_part = tag.split(':')[1]
        if weight_part.endswith('kg'):
            total += int(weight_part[:-2]) * 1000
        else:
            total += int(weight_part[:-1])
    return total

def count_booked_hours(schedule):
    if not schedule:
        return 0
    hours = 0
    for slot in schedule.split(','):
        start, end = slot.split('-')
        hours += int(end) - int(start)
    return hours

def calculate_receipt_total(lines):
    total = 0.0
    for line in lines:
        left, price_str = line.split(' @ $')
        qty_str = left.split('x ')[0]
        total += int(qty_str) * float(price_str)
    return round(total, 2)

def extract_winning_teams(results):
    winners = []
    for res in results:
        left, right = res.split(' - ')
        home_team, home_score = left.rsplit(' ', 1)
        away_score, away_team = right.split(' ', 1)
        if int(home_score) > int(away_score):
            winners.append(home_team)
        elif int(away_score) > int(home_score):
            winners.append(away_team)
    return winners

def final_drone_altitude(commands):
    altitude = 0
    for cmd in commands:
        direction, value = cmd.split(' ')
        if direction == 'UP':
            altitude += int(value)
        elif direction == 'DOWN':
            altitude -= int(value)
    return altitude

def plants_in_zone(codes, target_zone):
    species_list = []
    for code in codes:
        species, age, zone = code.split('/')
        if zone == target_zone:
            species_list.append(species)
    return species_list

def find_danger_spike(readings, threshold, margin):
    limit = threshold + margin
    for i, val in enumerate(readings):
        if val >= limit:
            return i
    return -1

def last_shelf_in_section(labels, section):
    for label in reversed(labels):
        if label.startswith(section):
            return label
    return None

def find_available_row(chart, k):
    target = [0] * k
    for r, row in enumerate(chart):
        for c in range(len(row) - k + 1):
            if row[c:c + k] == target:
                return r
    return -1

def find_song_by_duration(playlist, min_sec, max_sec):
    for title, duration in playlist:
        if min_sec <= duration <= max_sec:
            return title
    return ''

def find_min_parcel_index(weights, target):
    lo, hi = 0, len(weights) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if weights[mid] >= target:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

def locate_gate_tickets(tickets, gate):
    indices = []
    for idx, code in enumerate(tickets):
        if code.endswith(gate):
            indices.append(idx)
    return indices

def find_service_day(daily_miles, interval):
    total = 0
    for day, miles in enumerate(daily_miles):
        total += miles
        if total >= interval:
            return day
    return -1

def first_unpaired_crate(crates):
    counts = {}
    for c in crates:
        counts[c] = counts.get(c, 0) + 1
    for c in crates:
        if counts[c] == 1:
            return c
    return -1

def find_first_high_tide(heights):
    for i in range(1, len(heights) - 1):
        if heights[i] > heights[i - 1] and heights[i] > heights[i + 1]:
            return i
    return -1

def find_closest_room(rooms, target):
    best_room = None
    for name in sorted(rooms):
        diff = abs(rooms[name] - target)
        if best_room is None or diff < best_diff:
            best_room = name
            best_diff = diff
    return best_room

def find_available_rows(grid, k):
    result = []
    for r, row in enumerate(grid):
        streak = 0
        for seat in row:
            streak = streak + 1 if seat == 0 else 0
            if streak >= k:
                result.append(r)
                break
    return result

def sum_border_inventory(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    total = 0
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                total += grid[r][c]
    return total

def count_heat_spikes(grid):
    rows, cols = len(grid), len(grid[0])
    count = 0
    for r in range(1, rows - 1):
        for c in range(1, cols - 1):
            val = grid[r][c]
            if val > grid[r-1][c] and val > grid[r+1][c] and val > grid[r][c-1] and val > grid[r][c+1]:
                count += 1
    return count

def make_shelf_labels(rows, cols):
    grid = []
    for r in range(1, rows + 1):
        row_list = []
        for c in range(1, cols + 1):
            row_list.append(f"R{r}C{c}")
        grid.append(row_list)
    return grid

def wettest_station(grid):
    num_cols = len(grid[0])
    best_col = 0
    max_rain = -1
    for c in range(num_cols):
        col_sum = sum(grid[r][c] for r in range(len(grid)))
        if col_sum > max_rain:
            max_rain = col_sum
            best_col = c
    return best_col

def clamp_elevation_grid(grid):
    cleaned = []
    for row in grid:
        cleaned.append([max(0, val) for val in row])
    return cleaned

def score_drone_path(grid, moves):
    r, c = 0, 0
    total = grid[r][c]
    deltas = {'R': (0, 1), 'L': (0, -1), 'U': (-1, 0), 'D': (1, 0)}
    for m in moves:
        dr, dc = deltas[m]
        r += dr
        c += dc
        total += grid[r][c]
    return total

def are_plants_spaced(grid):
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                if r + 1 < rows and grid[r+1][c] == 1:
                    return False
                if c + 1 < cols and grid[r][c+1] == 1:
                    return False
    return True

def pool_tile_max(grid):
    rows, cols = len(grid), len(grid[0])
    out = []
    for r in range(0, rows, 2):
        new_row = []
        for c in range(0, cols, 2):
            block_max = max(grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1])
            new_row.append(block_max)
        out.append(new_row)
    return out

def toggle_mask_channels(mask, positions):
    for pos in positions:
        mask ^= (1 << pos)
    return mask

def extract_priority_codes(headers):
    codes = []
    for h in headers:
        codes.append((h >> 2) & 0xF)
    return codes

def count_busy_sensors(readings, k):
    count = 0
    for r in readings:
        if bin(r).count('1') >= k:
            count += 1
    return count

def pack_valve_states(states):
    result = 0
    for i, open_state in enumerate(states):
        if open_state:
            result |= (1 << i)
    return result

def first_open_seat(row_map):
    seat = 0
    while (row_map & 1) == 1:
        row_map >>= 1
        seat += 1
    return seat

def differing_feature_indices(config_a, config_b):
    diff = config_a ^ config_b
    indices = []
    idx = 0
    while diff > 0:
        if diff & 1:
            indices.append(idx)
        diff >>= 1
        idx += 1
    return indices

def mask_lowest_bits(pixel, k):
    if k <= 0:
        return pixel
    return (pixel >> k) << k

def common_role_permissions(roles):
    common = roles[0]
    for r in roles[1:]:
        common &= r
    return common

def count_fitting_songs(song_lengths, drive_duration):
    total = 0
    count = 0
    for length in song_lengths:
        if total + length <= drive_duration:
            total += length
            count += 1
        else:
            break
    return count

def max_coupon_discount(coupons, k, bill):
    coupons_sorted = sorted(coupons, reverse=True)
    chosen = coupons_sorted[:k]
    return min(bill, sum(chosen))

def count_shipping_crates(weights, limit):
    if not weights:
        return 0
    crates = 1
    current = 0
    for w in weights:
        if current + w <= limit:
            current += w
        else:
            crates += 1
            current = w
    return crates

def pair_kayak_riders(weights, limit):
    w = sorted(weights)
    left, right = 0, len(w) - 1
    pairs = 0
    while left < right:
        if w[left] + w[right] <= limit:
            pairs += 1
            left += 1
            right -= 1
        else:
            right -= 1
    return pairs

def min_labels_for_width(label_widths, target_width):
    total = 0
    count = 0
    for w in sorted(label_widths, reverse=True):
        if total >= target_width:
            break
        total += w
        count += 1
    return count if total >= target_width else -1

def fill_theater_row(row):
    seats = list(row)
    added = 0
    for i in range(len(seats)):
        if seats[i] == 0:
            left_empty = (i == 0) or (seats[i - 1] == 0)
            right_empty = (i == len(seats) - 1) or (seats[i + 1] == 0)
            if left_empty and right_empty:
                seats[i] = 1
                added += 1
    return added

def assign_drone_batteries(requirements, batteries):
    reqs = sorted(requirements)
    bats = sorted(batteries)
    i = j = 0
    while i < len(reqs) and j < len(bats):
        if bats[j] >= reqs[i]:
            i += 1
        j += 1
    return i

def filter_sensor_timestamps(timestamps, cooldown):
    if not timestamps:
        return 0
    count = 1
    last = timestamps[0]
    for t in timestamps[1:]:
        if t - last >= cooldown:
            count += 1
            last = t
    return count

def max_booth_revenue(prices, k):
    p = list(prices)
    revenue = 0
    for _ in range(k):
        best = max(p)
        if best <= 0:
            break
        revenue += best
        p[p.index(best)] -= 1
    return revenue

def shelf_digit_ratio(label):
    if not label:
        return 0.0
    digits = sum(1 for c in label if c.isdigit())
    return round(digits / len(label), 2)

def longest_title_word(titles):
    max_len = 0
    for title in titles:
        for word in title.split():
            if len(word) > max_len:
                max_len = len(word)
    return max_len

def count_alpha_heavy_tickets(tickets):
    count = 0
    for t in tickets:
        uppers = sum(1 for c in t if c.isupper())
        digits = sum(1 for c in t if c.isdigit())
        if uppers > digits:
            count += 1
    return count

def avg_sensor_fields(log_text):
    lines = [line for line in log_text.splitlines() if line.strip()]
    if not lines:
        return 0.0
    total_fields = sum(len(line.split(',')) for line in lines)
    return total_fields / len(lines)

def count_vip_occupied(seat_map):
    total = 0
    for row in seat_map:
        if row.startswith('VIP'):
            total += row[3:].count('X')
    return total

def hashtag_lengths(post):
    result = {}
    for word in post.split():
        if word.startswith('#') and len(word) > 1:
            result[word] = len(word) - 1
    return result

def review_word_span(reviews):
    if not reviews:
        return 0
    counts = [len(r.split()) for r in reviews]
    return max(counts) - min(counts)

def past_tense_percentage(recipe):
    words = [w.strip('.,!;:') for w in recipe.split()]
    if not words:
        return 0.0
    ed_words = sum(1 for w in words if w.lower().endswith('ed'))
    return round((ed_words / len(words)) * 100, 1)

def count_server_countries(addresses):
    countries = set()
    for addr in addresses:
        if ':' in addr:
            prefix = addr.split(':')[0]
            if len(prefix) == 2 and prefix.isalpha():
                countries.add(prefix.upper())
    return len(countries)

def count_expressive_marks(messages):
    total = 0
    for msg in messages:
        for char in msg:
            if char in '!?':
                total += 1
    return total

def parse_shelf_label(label):
    parts = label.split('-')
    aisle = parts[0]
    rack = int(parts[1])
    bin_num = int(parts[2])
    return (aisle, rack, bin_num)

def find_open_seats(row_map):
    open_seats = []
    for idx, seat in enumerate(row_map):
        if seat == 'O':
            open_seats.append(idx + 1)
    return open_seats

def parse_ticket_codes(tickets):
    result = []
    for ticket in tickets:
        sec, row, seat = ticket.split(':')
        result.append((sec, int(row), int(seat)))
    return result

def parse_int_query(url):
    if '?' not in url:
        return {}
    _, query = url.split('?', 1)
    params = {}
    for pair in query.split('&'):
        k, v = pair.split('=')
        params[k] = int(v)
    return params

def get_winning_teams(matches):
    winners = []
    for match in matches:
        left, right = match.split(' - ')
        team_a, score_a = left.rsplit(' ', 1)
        score_b, team_b = right.split(' ', 1)
        if int(score_a) > int(score_b):
            winners.append(team_a)
        elif int(score_b) > int(score_a):
            winners.append(team_b)
    return winners

def decode_short_rle(encoded):
    result = []
    for i in range(0, len(encoded), 2):
        count = int(encoded[i])
        char = encoded[i + 1]
        result.append(char * count)
    return ''.join(result)

def build_shelf_labels(rows, cols):
    grid = []
    for r in range(1, rows + 1):
        row_labels = [f"R{r}C{c}" for c in range(1, cols + 1)]
        grid.append(row_labels)
    return grid

def wettest_region_column(rainfall_grid):
    num_cols = len(rainfall_grid[0])
    best_col = 0
    max_rain = -1
    for c in range(num_cols):
        col_sum = sum(rainfall_grid[r][c] for r in range(len(rainfall_grid)))
        if col_sum > max_rain:
            max_rain = col_sum
            best_col = c
    return best_col

def clamp_image_pixels(image, low, high):
    result = []
    for row in image:
        new_row = []
        for val in row:
            if val < low:
                new_row.append(0)
            elif val > high:
                new_row.append(255)
            else:
                new_row.append(val)
        result.append(new_row)
    return result

def is_stable_stack(crates):
    for r in range(len(crates) - 1):
        for c in range(len(crates[0])):
            if crates[r][c] > crates[r + 1][c]:
                return False
    return True

def locate_damaged_tiles(floor):
    coords = []
    for r in range(len(floor)):
        for c in range(len(floor[r])):
            if floor[r][c] == 'X':
                coords.append((r, c))
    return coords

def rotate_schedule_right(schedule):
    if not schedule or not schedule[0]:
        return schedule
    return [[row[-1]] + row[:-1] for row in schedule]

def average_sensor_temp(readings, target_id):
    temps = [temp for sid, _, temp in readings if sid == target_id]
    if not temps:
        return 0.0
    return sum(temps) / len(temps)

def convert_playlist_lengths(tracks):
    result = []
    for title, mins, secs in tracks:
        result.append((title, mins * 60 + secs))
    return result

def find_low_stock_shelves(shelves, threshold):
    low_stock = []
    for aisle, bay, count in shelves:
        if count < threshold:
            low_stock.append((aisle, bay))
    return low_stock

def total_ticket_revenue(tickets):
    total = 0
    for code, price, fee in tickets:
        if code.startswith('VIP'):
            total += price + fee
        else:
            total += price
    return total

def cheapest_available_seat(seats):
    available = [(price, row, num) for row, num, price, occupied in seats if not occupied]
    if not available:
        return ()
    _, best_row, best_num = min(available)
    return (best_row, best_num)

def reroute_heavy_parcels(parcels, weight_limit):
    updated = []
    for sender, receiver, weight in parcels:
        if weight > weight_limit:
            updated.append((receiver, sender, weight))
        else:
            updated.append((sender, receiver, weight))
    return updated

def summarize_lap_times(laps):
    totals = {}
    for name, _, duration in laps:
        totals[name] = totals.get(name, 0) + duration
    return sorted(totals.items())

def merge_menu_prices(menu1, menu2):
    prices = {}
    for dish, price in menu1 + menu2:
        if dish not in prices or price > prices[dish]:
            prices[dish] = price
    return sorted(prices.items())

def count_delayed_flights(flights, min_delay):
    count = 0
    for _, scheduled, actual in flights:
        if actual - scheduled >= min_delay:
            count += 1
    return count

def list_overdue_loans(loans):
    overdue = []
    for code, borrower, kept, limit in loans:
        if kept > limit:
            overdue.append((code, borrower))
    return overdue

def find_sudden_jump(readings, threshold):
    for i in range(1, len(readings)):
        if readings[i] - readings[i - 1] > threshold:
            return i
    return -1

def last_even_shelf(labels, aisle):
    for label in reversed(labels):
        if label.startswith(aisle) and label[-1] in '02468':
            return label
    return None

def find_group_row(grid, k):
    target = [0] * k
    for r, row in enumerate(grid):
        for c in range(len(row) - k + 1):
            if row[c:c + k] == target:
                return r
    return -1

def closest_song_title(playlist, target):
    best_title, best_diff = playlist[0][0], abs(playlist[0][1] - target)
    for title, duration in playlist[1:]:
        diff = abs(duration - target)
        if diff < best_diff:
            best_title, best_diff = title, diff
    return best_title

def find_out_of_spec_batches(batches, min_weight, max_weight):
    flagged = []
    for batch_id, weight in batches:
        if weight < min_weight or weight > max_weight:
            flagged.append(batch_id)
    return flagged

def next_higher_price(prices, voucher):
    low, high = 0, len(prices) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if prices[mid] > voucher:
            result = prices[mid]
            high = mid - 1
        else:
            low = mid + 1
    return result

def first_unscanned_vip(queue, vip_codes, scanned_codes):
    for code in queue:
        if code in vip_codes and code not in scanned_codes:
            return code
    return ''

def second_beacon_index(log, beacon_id):
    seen = 0
    for idx, entry in enumerate(log):
        if entry == beacon_id:
            seen += 1
            if seen == 2:
                return idx
    return -1

def find_suitable_room(rooms, n):
    for room in rooms:
        if room['capacity'] >= n and room['projector']:
            return room['name']
    return 'None'

def first_crest_day(levels):
    for i in range(1, len(levels) - 1):
        if levels[i] > levels[i - 1] and levels[i] > levels[i + 1]:
            return i
    return -1

def min_shelf_compartments(book_widths, shelf_width):
    if not book_widths:
        return 0
    shelves = 1
    current_width = 0
    for w in book_widths:
        if current_width + w <= shelf_width:
            current_width += w
        else:
            shelves += 1
            current_width = w
    return shelves

def min_jackets_needed(warmth_ratings, target):
    if target <= 0:
        return 0
    current = 0
    count = 0
    for w in sorted(warmth_ratings, reverse=True):
        current += w
        count += 1
        if current >= target:
            return count
    return -1

def assign_hotel_rooms(group_sizes, room_sizes):
    groups = sorted(group_sizes)
    rooms = sorted(room_sizes)
    g = 0
    for r in rooms:
        if g < len(groups) and r >= groups[g]:
            g += 1
    return g

def count_logged_readings(timestamps, cooldown):
    if not timestamps:
        return 0
    count = 1
    last_time = timestamps[0]
    for t in timestamps[1:]:
        if t - last_time >= cooldown:
            count += 1
            last_time = t
    return count

def max_clearance_profit(prices, base_cost, k):
    profits = [p - base_cost for p in prices if p > base_cost]
    profits.sort(reverse=True)
    return sum(profits[:k])

def min_cable_slack(workstations, ports):
    ws = sorted(workstations)
    ps = sorted(ports)
    if len(ws) != len(ps):
        return -1
    total = 0
    for w, p in zip(ws, ps):
        if p < w:
            return -1
        total += p - w
    return total

def max_couple_seats(row_layout):
    pairs = 0
    i = 0
    while i < len(row_layout) - 1:
        if row_layout[i] == 'E' and row_layout[i + 1] == 'E':
            pairs += 1
            i += 2
        else:
            i += 1
    return pairs

def final_clearance_level(initial_level, badges):
    level = initial_level
    for threshold, gain in sorted(badges):
        if level >= threshold:
            level += gain
        else:
            break
    return level

def sort_shelf_labels(labels):
    def label_key(label):
        aisle, bay = label.split('-')
        return (int(bay), aisle)
    return sorted(labels, key=label_key)

def sort_song_durations(durations):
    def to_seconds(d):
        m, s = d.split(':')
        return int(m) * 60 + int(s)
    return sorted(durations, key=to_seconds)

def sort_ticket_codes(tickets):
    order = {'H': 0, 'M': 1, 'L': 2}
    return sorted(tickets, key=lambda t: (order[t[0]], int(t[1:])))

def sort_filenames_by_ext(filenames):
    def file_key(name):
        base, ext = name.split('.')
        return (ext, base)
    return sorted(filenames, key=file_key)

def first_song_reaching_time(lengths, target_time):
    elapsed = 0
    for i, length in enumerate(lengths):
        elapsed += length
        if elapsed >= target_time:
            return i
    return -1

def query_rainfall_totals(daily_rain, date_ranges):
    prefix = [0]
    for rain in daily_rain:
        prefix.append(prefix[-1] + rain)
    return [prefix[end + 1] - prefix[start] for start, end in date_ranges]

def count_milestone_days(daily_steps, milestone):
    total = 0
    hits = 0
    for steps in daily_steps:
        total += steps
        if total % milestone == 0:
            hits += 1
    return hits

def trail_distance_markers(segments):
    markers = [0]
    for seg in segments:
        markers.append(markers[-1] + seg)
    return markers

def count_loadable_packages(weights, max_weight):
    total = 0
    count = 0
    for w in weights:
        if total + w > max_weight:
            break
        total += w
        count += 1
    return count

def highest_drone_altitude(start_alt, steps):
    current = start_alt
    peak = start_alt
    for step in steps:
        current += step
        if current > peak:
            peak = current
    return peak

def hourly_temperature_shifts(cumulative_changes):
    if not cumulative_changes:
        return []
    shifts = [cumulative_changes[0]]
    for i in range(1, len(cumulative_changes)):
        shifts.append(cumulative_changes[i] - cumulative_changes[i - 1])
    return shifts

def verify_planned_stops(planned, route_log):
    p_idx = 0
    for station in route_log:
        if p_idx < len(planned) and station == planned[p_idx]:
            p_idx += 1
    return p_idx == len(planned)

def common_sensor_timestamps(log_a, log_b):
    i, j = 0, 0
    result = []
    while i < len(log_a) and j < len(log_b):
        if log_a[i] == log_b[j]:
            if not result or result[-1] != log_a[i]:
                result.append(log_a[i])
            i += 1
            j += 1
        elif log_a[i] < log_b[j]:
            i += 1
        else:
            j += 1
    return result

def reverse_locked_seats(seats):
    res = list(seats)
    left, right = 0, len(res) - 1
    while left < right:
        if res[left] == 0:
            left += 1
        elif res[right] == 0:
            right -= 1
        else:
            res[left], res[right] = res[right], res[left]
            left += 1
            right -= 1
    return res

def deduplicate_temp_readings(readings):
    if not readings:
        return []
    result = [readings[0]]
    for i in range(1, len(readings)):
        if readings[i] != readings[i - 1]:
            result.append(readings[i])
    return result

def find_commute_song_pair(durations, target_time):
    left, right = 0, len(durations) - 1
    while left < right:
        current = durations[left] + durations[right]
        if current == target_time:
            return (durations[left], durations[right])
        elif current < target_time:
            left += 1
        else:
            right -= 1
    return None

def is_symmetric_ribbon(colors):
    left, right = 0, len(colors) - 1
    while left < right:
        if colors[left] != colors[right]:
            return False
        left += 1
        right -= 1
    return True

def interleave_ticket_queues(vip_queue, regular_queue):
    i, j = 0, 0
    merged = []
    while i < len(vip_queue) or j < len(regular_queue):
        if i < len(vip_queue):
            merged.append(vip_queue[i])
            i += 1
        if j < len(regular_queue):
            merged.append(regular_queue[j])
            j += 1
    return merged

def count_matched_applicants(scores, requirements):
    s_idx, r_idx = 0, 0
    matches = 0
    while s_idx < len(scores) and r_idx < len(requirements):
        if scores[s_idx] >= requirements[r_idx]:
            matches += 1
            s_idx += 1
            r_idx += 1
        else:
            s_idx += 1
    return matches

def push_empty_stock_to_end(quantities):
    res = list(quantities)
    write_idx = 0
    for read_idx in range(len(res)):
        if res[read_idx] != 0:
            res[write_idx], res[read_idx] = res[read_idx], res[write_idx]
            write_idx += 1
    return res

def find_sensor_peaks(readings):
    peaks = []
    for i in range(1, len(readings) - 1):
        if readings[i] > readings[i - 1] and readings[i] > readings[i + 1]:
            peaks.append(readings[i])
    return peaks

def cumulative_playlist_times(tracks, limit):
    result = []
    total = 0
    for t in tracks:
        if total + t > limit:
            break
        total += t
        result.append(total)
    return result

def compress_shelf_labels(labels):
    if not labels:
        return []
    res = []
    curr = labels[0]
    count = 1
    for label in labels[1:]:
        if label == curr:
            count += 1
        else:
            res.append(f"{curr}_{count}")
            curr = label
            count = 1
    res.append(f"{curr}_{count}")
    return res

def assign_parcel_trucks(weights):
    truck1, truck2 = [], []
    sum1, sum2 = 0, 0
    for w in weights:
        if sum1 <= sum2:
            truck1.append(w)
            sum1 += w
        else:
            truck2.append(w)
            sum2 += w
    return [truck1, truck2]

def scale_recipe_amounts(amounts, target_first):
    if not amounts:
        return []
    factor = target_first / amounts[0]
    return [round(a * factor, 1) for a in amounts]

def extract_withdrawal_amounts(balances):
    withdrawals = []
    for i in range(1, len(balances)):
        diff = balances[i] - balances[i - 1]
        if diff < 0:
            withdrawals.append(-diff)
    return withdrawals

def patch_error_logs(codes):
    result = []
    last_valid = None
    for c in codes:
        if c >= 0:
            last_valid = c
            result.append(c)
        else:
            result.append(last_valid if last_valid is not None else c)
    return result

def calculate_win_margins(scores):
    margins = []
    for i in range(0, len(scores) - 1, 2):
        diff = abs(scores[i] - scores[i + 1])
        if diff > 0:
            margins.append(diff)
    return margins

def get_zone_bays(labels, target_zone):
    bays = []
    for label in labels:
        zone, bay, level = label.split('-')
        if zone == target_zone:
            bays.append(int(bay))
    return bays

def count_open_seats(seat_map, row_index):
    rows = seat_map.split('/')
    if row_index < 0 or row_index >= len(rows):
        return 0
    return rows[row_index].count('O')

def expand_page_ranges(page_spec):
    if not page_spec:
        return []
    pages = []
    for part in page_spec.split(','):
        if '-' in part:
            start, end = part.split('-')
            pages.extend(range(int(start), int(end) + 1))
        else:
            pages.append(int(part))
    return pages

def parse_config_lines(config_text):
    config = {}
    for line in config_text.splitlines():
        line = line.strip()
        if line and not line.startswith('#'):
            key, val = line.split('=', 1)
            config[key.strip()] = val.strip()
    return config

def home_goal_difference(score_line):
    if not score_line:
        return 0
    diff = 0
    for period in score_line.split():
        home, away = period.split(':')
        diff += int(home) - int(away)
    return diff

def unpack_ticket_code(ticket):
    event, section, row, seat = ticket.split('-')
    return (event, section, row, int(seat))

def flights_before_cutoff(departures, cutoff):
    early_flights = []
    for entry in departures:
        flight, time_str = entry.split('|')
        if time_str < cutoff:
            early_flights.append(flight)
    return early_flights

def toggle_shelf_flags(flag, positions):
    for pos in positions:
        flag ^= (1 << pos)
    return flag

def extract_zone_code(ticket, p, k):
    mask = (1 << k) - 1
    return (ticket >> p) & mask

def count_even_parity_readings(readings):
    count = 0
    for r in readings:
        if bin(r).count('1') % 2 == 0:
            count += 1
    return count

def build_alarm_mask(rooms):
    mask = 0
    for r in rooms:
        mask |= (1 << r)
    return mask

def shared_access_bits(badge1, badge2):
    common = badge1 & badge2
    return bin(common).count('1')

def active_schedule_days(mask):
    days = []
    idx = 0
    while mask > 0:
        if mask & 1:
            days.append(idx)
        mask >>= 1
        idx += 1
    return days

def rotate_light_pattern(pattern, d):
    d %= 8
    return ((pattern << d) | (pattern >> (8 - d))) & 0xFF

def set_packet_priority(header, p, priority):
    clear_mask = ~(7 << p)
    return (header & clear_mask) | ((priority & 7) << p)

def refill_end_weekday(start_day, total_pills, pills_per_day):
    days_lasted = (total_pills + pills_per_day - 1) // pills_per_day
    return (start_day + days_lasted - 1) % 7

def count_shipping_weekdays(start_day, calendar_days):
    business_days = 0
    for d in range(calendar_days):
        if (start_day + d) % 7 < 5:
            business_days += 1
    return business_days

def locate_festival_day(day_of_year, month_lengths):
    for idx, length in enumerate(month_lengths):
        if day_of_year <= length:
            return (idx + 1, day_of_year)
        day_of_year -= length
    return (-1, -1)

def term_week_number(day_number, first_day_weekday):
    adjusted_day = day_number + first_day_weekday - 1
    return (adjusted_day // 7) + 1

def days_until_joint_check(cycle_a, since_a, cycle_b, since_b):
    for day in range(1, cycle_a * cycle_b + 1):
        if (since_a + day) % cycle_a == 0 and (since_b + day) % cycle_b == 0:
            return day
    return -1

def nth_weekday_of_month(start_weekday, target_weekday, n):
    first_occurrence = 1 + (target_weekday - start_weekday) % 7
    return first_occurrence + (n - 1) * 7

def workout_plan_span(start_weekday, gym_days, total_workouts):
    days_elapsed = 0
    completed = 0
    while completed < total_workouts:
        if (start_weekday + days_elapsed) % 7 in gym_days:
            completed += 1
        days_elapsed += 1
    return days_elapsed

def count_paired_parcels(weights, limit):
    left, right = 0, len(weights) - 1
    pairs = 0
    while left < right:
        if weights[left] + weights[right] <= limit:
            pairs += 1
            left += 1
            right -= 1
        else:
            right -= 1
    return pairs * 2

def is_row_symmetric(row):
    left, right = 0, len(row) - 1
    while left < right:
        if row[left] == 'X':
            left += 1
        elif row[right] == 'X':
            right -= 1
        elif row[left] != row[right]:
            return False
        else:
            left += 1
            right -= 1
    return True

def common_shelf_codes(inv_a, inv_b):
    i, j = 0, 0
    result = []
    while i < len(inv_a) and j < len(inv_b):
        if inv_a[i] < inv_b[j]:
            i += 1
        elif inv_a[i] > inv_b[j]:
            j += 1
        else:
            if not result or result[-1] != inv_a[i]:
                result.append(inv_a[i])
            i += 1
            j += 1
    return result

def reverse_serial_digits(code):
    chars = list(code)
    left, right = 0, len(chars) - 1
    while left < right:
        if not chars[left].isdigit():
            left += 1
        elif not chars[right].isdigit():
            right -= 1
        else:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    return ''.join(chars)

def weave_playlist(durations):
    left, right = 0, len(durations) - 1
    woven = []
    while left <= right:
        woven.append(durations[left])
        if left < right:
            woven.append(durations[right])
        left += 1
        right -= 1
    return woven

def verify_runner_checkpoints(runner_log, sensor_feed):
    i, j = 0, 0
    while i < len(runner_log) and j < len(sensor_feed):
        if runner_log[i] == sensor_feed[j]:
            i += 1
        j += 1
    return i == len(runner_log)

def deduplicate_readings(readings):
    if not readings:
        return []
    result = [readings[0]]
    for r in readings[1:]:
        if r != result[-1]:
            result.append(r)
    return result

def closest_badge_gap(dept_a, dept_b):
    i, j = 0, 0
    best = abs(dept_a[0] - dept_b[0])
    while i < len(dept_a) and j < len(dept_b):
        diff = abs(dept_a[i] - dept_b[j])
        if diff < best:
            best = diff
        if dept_a[i] < dept_b[j]:
            i += 1
        else:
            j += 1
    return best

def count_qualifying_voucher_pairs(vouchers, threshold):
    left, right = 0, len(vouchers) - 1
    count = 0
    while left < right:
        if vouchers[left] + vouchers[right] > threshold:
            count += right - left
            right -= 1
        else:
            left += 1
    return count

def trim_mirror_noise(signal):
    left, right = 0, len(signal) - 1
    while left < right and signal[left] == signal[right]:
        left += 1
        right -= 1
    return signal[left:right + 1]

def max_workout_songs(song_lengths, duration):
    count = 0
    for length in sorted(song_lengths):
        if duration >= length:
            duration -= length
            count += 1
        else:
            break
    return count

def best_exhibit_ratings(exhibits, k, max_energy):
    ordered = sorted(exhibits, key=lambda x: (-x[0], x[1]))
    total_rating = 0
    picked = 0
    for rating, cost in ordered:
        if picked < k and cost <= max_energy:
            total_rating += rating
            max_energy -= cost
            picked += 1
    return total_rating

def count_delivery_crates(weights, limit):
    if not weights:
        return 0
    crates = 1
    current = 0
    for w in weights:
        if current + w <= limit:
            current += w
        else:
            crates += 1
            current = w
    return crates

def seat_cafe_groups(groups, tables):
    groups = sorted(groups)
    tables = sorted(tables)
    g = 0
    for t in tables:
        if g < len(groups) and t >= groups[g]:
            g += 1
    return g

def min_backup_batteries(batteries, target_voltage):
    total = 0
    count = 0
    for b in sorted(batteries, reverse=True):
        if total >= target_voltage:
            break
        total += b
        count += 1
    return count if total >= target_voltage else -1

def max_crate_profit(batches, limit):
    profit = 0
    for qty, price in sorted(batches, key=lambda x: x[1], reverse=True):
        take = min(qty, limit)
        profit += take * price
        limit -= take
        if limit == 0:
            break
    return profit

def count_sprinklers_used(ranges, n):
    pos = 0
    used = 0
    for r in ranges:
        if pos >= n:
            break
        pos += r
        used += 1
    return used if pos >= n else -1

def count_canoe_pairs(weights, limit):
    w = sorted(weights)
    left, right = 0, len(w) - 1
    pairs = 0
    while left < right:
        if w[left] + w[right] <= limit:
            pairs += 1
            left += 1
            right -= 1
        else:
            right -= 1
    return pairs

def count_shipping_boxes(weights, limit):
    if not weights:
        return 0
    boxes = 1
    current = 0
    for w in weights:
        if current + w > limit:
            boxes += 1
            current = w
        else:
            current += w
    return boxes

def min_backup_drives(capacities, data_size):
    if data_size <= 0:
        return 0
    used = 0
    for cap in sorted(capacities, reverse=True):
        data_size -= cap
        used += 1
        if data_size <= 0:
            return used
    return -1

def count_filtered_readings(readings, threshold):
    if not readings:
        return 0
    count = 1
    last = readings[0]
    for r in readings[1:]:
        if abs(r - last) >= threshold:
            count += 1
            last = r
    return count

def max_coupon_points(coupons, spend, k):
    eligible = [pts for req, pts in coupons if spend >= req]
    eligible.sort(reverse=True)
    return sum(eligible[:k])

def assign_visitor_badges(visitors, badges):
    visitors = sorted(visitors)
    badges = sorted(badges)
    v_idx = 0
    for b in badges:
        if v_idx < len(visitors) and b >= visitors[v_idx]:
            v_idx += 1
    return v_idx

def seat_patrons_spaced(row):
    chairs = list(row)
    added = 0
    for i in range(len(chairs)):
        if chairs[i] == 0:
            left_ok = (i == 0 or chairs[i - 1] == 0)
            right_ok = (i == len(chairs) - 1 or chairs[i + 1] == 0)
            if left_ok and right_ok:
                chairs[i] = 1
                added += 1
    return added

def assign_courier_jobs(couriers, jobs):
    jobs_sorted = sorted(jobs, key=lambda x: x[1], reverse=True)
    used = [False] * len(jobs_sorted)
    total = 0
    for limit in sorted(couriers):
        for i, (weight, pay) in enumerate(jobs_sorted):
            if not used[i] and weight <= limit:
                used[i] = True
                total += pay
                break
    return total

def advance_warehouse_clock(week, day, hour, add_hours):
    total_hours = (week * 7 * 24) + (day * 24) + hour + add_hours
    new_week = total_hours // (7 * 24)
    rem_hours = total_hours % (7 * 24)
    return (new_week, rem_hours // 24, rem_hours % 24)

def planetary_day_to_month(day_of_year, month_lengths):
    for idx, length in enumerate(month_lengths):
        if day_of_year <= length:
            return (idx + 1, day_of_year)
        day_of_year -= length
    return (-1, -1)

def shared_maintenance_days(start_a, period_a, start_b, period_b, total_days):
    days_a = set(range(start_a, total_days + 1, period_a))
    days_b = set(range(start_b, total_days + 1, period_b))
    return sorted(list(days_a & days_b))

def booking_overlap_days(booking1, booking2):
    start = max(booking1[0], booking2[0])
    end = min(booking1[1], booking2[1])
    return max(0, end - start + 1)

def get_fiscal_quarter(month, fiscal_start_month):
    months_elapsed = (month - fiscal_start_month) % 12
    return (months_elapsed // 3) + 1

def find_spike_indices(readings):
    spikes = []
    for i in range(1, len(readings) - 1):
        if readings[i] > (readings[i - 1] + readings[i + 1]) / 2:
            spikes.append(i)
    return spikes

def trim_playlist(durations, limit):
    result = list(durations)
    while sum(result) > limit and result:
        result.pop()
    return result

def third_ticket_refund(prices):
    total = 0
    for i in range(2, len(prices), 3):
        total += prices[i]
    return total

def carry_forward_balance(balances):
    result = []
    last_positive = 0
    for b in balances:
        if b > 0:
            last_positive = b
            result.append(b)
        elif b < 0:
            result.append(last_positive)
        else:
            result.append(0)
    return result

def count_adjacent_empty_seats(row):
    count = 0
    for i in range(len(row)):
        if row[i] == 0:
            left = (i > 0 and row[i - 1] == 1)
            right = (i < len(row) - 1 and row[i + 1] == 1)
            if left or right:
                count += 1
    return count

def schedule_deliveries(urgent, normal):
    schedule = []
    u_idx, n_idx = 0, 0
    while u_idx < len(urgent) or n_idx < len(normal):
        for _ in range(2):
            if u_idx < len(urgent):
                schedule.append(urgent[u_idx])
                u_idx += 1
        if n_idx < len(normal):
            schedule.append(normal[n_idx])
            n_idx += 1
    return schedule

def personal_best_laps(lap_times):
    if not lap_times:
        return []
    bests = [lap_times[0]]
    fastest = lap_times[0]
    for t in lap_times[1:]:
        if t < fastest:
            bests.append(t)
            fastest = t
    return bests

def group_contiguous_batches(serials):
    if not serials:
        return []
    groups = [[serials[0]]]
    for s in serials[1:]:
        if s - groups[-1][-1] <= 1:
            groups[-1].append(s)
        else:
            groups.append([s])
    return groups

def count_alert_readings(readings, alert_ranges):
    count = 0
    for r in readings:
        if any(low < r < high for low, high in alert_ranges):
            count += 1
    return count

def unoccupied_seats(row_size, reserved):
    taken = 0
    for start, end in reserved:
        taken += (end - start + 1)
    return row_size - taken

def shared_broadcast_time(show_a, show_b):
    start = max(show_a[0], show_b[0])
    end = min(show_a[1], show_b[1])
    return max(0, end - start)

def expand_ticket_batches(batches):
    tickets = set()
    for start, end in batches:
        tickets.update(range(start, end + 1))
    return sorted(tickets)

def filter_delivery_windows(windows, min_duration):
    valid = []
    for start, end in windows:
        if end - start >= min_duration:
            valid.append((start, end))
    return valid

def longest_idle_gap(shifts):
    max_gap = 0
    for i in range(1, len(shifts)):
        gap = shifts[i][0] - shifts[i - 1][1]
        if gap > max_gap:
            max_gap = gap
    return max_gap

def is_maintenance_covered(window, duty_schedule):
    w_start, w_end = window
    for d_start, d_end in duty_schedule:
        if d_start <= w_start and w_end <= d_end:
            return True
    return False

import math

def count_linked_crates(weights, limit):
    count = 0
    for w in weights:
        if math.gcd(w, limit) > 1:
            count += 1
    return count

def find_ticket_number(a, rem_a, b, rem_b):
    n = 1
    while True:
        if n % a == rem_a and n % b == rem_b:
            return n
        n += 1

def sum_shelf_capacities(box_count):
    total = 0
    for shelf in range(1, box_count):
        if box_count % shelf == 0:
            total += shelf
    return total

def max_signal_exponent(frequency, base):
    power = 0
    while frequency % base == 0:
        frequency //= base
        power += 1
    return power

def count_hallway_zones(rooms, hallway_len):
    remainders = set()
    for r in rooms:
        remainders.add(r % hallway_len)
    return len(remainders)

import math

def are_gears_compatible(gear_a, gear_b, margin):
    return math.gcd(gear_a, gear_b) <= margin

import math

def next_batch_size(target, size_a, size_b):
    step = (size_a * size_b) // math.gcd(size_a, size_b)
    if target % step == 0:
        return target
    return ((target // step) + 1) * step

def find_group_seats(row, group_size):
    indices = []
    n = len(row)
    for i in range(n - group_size + 1):
        if all(seat == 0 for seat in row[i:i + group_size]):
            indices.append(i)
    return indices

def get_matching_bays(labels, target_aisle, target_level):
    bays = []
    for label in labels:
        aisle, bay, level = label.split('-')
        if aisle == target_aisle and int(level) == target_level:
            bays.append(int(bay))
    return bays

def flag_heavy_packages(weights):
    if not weights:
        return []
    limit = (sum(weights) / len(weights)) * 1.5
    return [i for i, w in enumerate(weights) if w > limit]

def compress_weather_streaks(codes):
    if not codes:
        return []
    streaks = []
    curr_code = codes[0]
    count = 1
    for code in codes[1:]:
        if code == curr_code:
            count += 1
        else:
            streaks.append((curr_code, count))
            curr_code = code
            count = 1
    streaks.append((curr_code, count))
    return streaks

def scale_recipe_quantities(quantities, orig_servings, target_servings):
    factor = target_servings / orig_servings
    return [round(q * factor, 1) for q in quantities]

def spillover_server_loads(loads, cap):
    if not loads:
        return []
    result = list(loads)
    for i in range(len(result) - 1):
        if result[i] > cap:
            excess = result[i] - cap
            result[i] = cap
            result[i + 1] += excess
    return result

def filter_long_tracks(playlist, min_seconds):
    result = []
    for title, artist, seconds in playlist:
        if seconds > min_seconds:
            result.append(title)
    return tuple(result)

def aisle_stock_value(inventory, target_aisle):
    total = 0
    for aisle, name, qty, price in inventory:
        if aisle == target_aisle:
            total += qty * price
    return total

def widest_range_sensor(readings):
    best_id = readings[0][0]
    max_drop = readings[0][2] - readings[0][1]
    for sensor_id, low, high in readings[1:]:
        if high - low > max_drop:
            max_drop = high - low
            best_id = sensor_id
    return best_id

def reverse_flight_routes(flights):
    reversed_list = []
    for code, origin, dest in flights:
        reversed_list.append((code, dest, origin))
    return reversed_list

def available_seat_codes(seat_map):
    open_seats = []
    for row, num, taken in seat_map:
        if not taken:
            open_seats.append(f"{row}{num}")
    return tuple(open_seats)

def add_heavy_surcharge(packages, weight_limit, fee):
    updated = []
    for tid, weight, cost in packages:
        if weight > weight_limit:
            updated.append((tid, weight, cost + fee))
        else:
            updated.append((tid, weight, cost))
    return updated

def combine_exam_scores(midterms, finals):
    combined = []
    for i in range(len(midterms)):
        combined.append((midterms[i][0], midterms[i][1], finals[i][1]))
    return combined

def count_occupied_rooms(bookings, query_day):
    occupied = 0
    for guest, start, end in bookings:
        if start <= query_day < end:
            occupied += 1
    return occupied

def size_price_bounds(menu, target_size):
    prices = [price for name, size, price in menu if size == target_size]
    return (min(prices), max(prices))

def cashier_shift_summary(receipts, cashier_id):
    total = 0
    count = 0
    for cid, amount in receipts:
        if cid == cashier_id:
            total += amount
            count += 1
    return (total, count)

def delivery_dates_in_month(month_length, start_weekday, target_weekday):
    offset = (target_weekday - start_weekday) % 7
    first_day = 1 + offset
    return list(range(first_day, month_length + 1, 7))

def count_course_weeks(start_weekday, duration_days):
    if duration_days <= 0:
        return 0
    total_span = start_weekday + duration_days
    return (total_span + 6) // 7

def kth_meeting_day(start_weekday, target_weekday, k):
