    total = 0
    for tray in range(min_tray, max_tray + 1):
        total += batch % tray
    return total

def next_odd_divisor_gear(min_limit):
    n = min_limit + 1
    while True:
        divisors = sum(1 for i in range(1, n + 1) if n % i == 0)
        if divisors % 2 == 1:
            return n
        n += 1

def exclusive_beacon_ids(n, freq_a, freq_b):
