        aisle, bay = code.split('-')
        return (int(bay), aisle)
    return sorted(codes, key=parse_code)

def sort_plane_seats(seats):
    def seat_key(s):
        return (int(s[:-1]), -ord(s[-1]))
    return sorted(seats, key=seat_key)

def sort_by_discounted_price(items):
    def final_price(item):
        return item[1] * (100 - item[2]) / 100.0
    return sorted(items, key=final_price)

def sort_support_tickets(tickets):
    priority = {'URG': 1, 'HIGH': 2, 'LOW': 3}
    def ticket_key(t):
        level, num = t.split('-')
        return (priority[level], int(num))
    return sorted(tickets, key=ticket_key)

def sort_shipping_boxes(boxes):
    def box_key(b):
        l, w, h = b
        return (l * w * h, max(l, w, h))
    return sorted(boxes, key=box_key)

def sort_emails_by_domain(emails):
    def email_key(e):
        user, domain = e.split('@')
        return (domain, user)
    return sorted(emails, key=email_key)

def sort_team_standings(teams):
    def standing_key(t):
        name, wins, draws = t
        return (-(wins * 3 + draws), name)
    return sorted(teams, key=standing_key)

def sort_course_codes(courses):
    def course_key(c):
        dept = ''.join(ch for ch in c if ch.isalpha())
        num = int(''.join(ch for ch in c if ch.isdigit()))
        return (num, dept)
    return sorted(courses, key=course_key)

def get_occupied_seats(row_bitmap):
    seats = []
    index = 0
    while row_bitmap > 0:
        if row_bitmap & 1:
            seats.append(index)
        row_bitmap >>= 1
        index += 1
    return seats

def toggle_lamps(lamp_mask, positions):
    for pos in positions:
        lamp_mask ^= (1 << pos)
    return lamp_mask

def decode_weather_payload(payload):
    direction = (payload >> 8) & 0x0F
    speed = payload & 0xFF
    return (direction, speed)

def filter_cleared_badges(badges, required_mask):
    valid = []
    for badge in badges:
        if (badge & required_mask) == required_mask:
            valid.append(badge)
    return valid

def calculate_packet_checksum(packet_bytes):
