        if elapsed >= target:
            return i
    return -1

def sum_sales_periods(daily_sales, periods):
    prefix = [0]
    for s in daily_sales:
        prefix.append(prefix[-1] + s)
    return [prefix[end + 1] - prefix[start] for start, end in periods]

def count_fitting_books(thicknesses, shelf_width):
