        mask ^= (1 << pos)
    return mask

def extract_header_field(header, k, w):
    mask = (1 << w) - 1
    return (header >> k) & mask

def occupied_seat_indices(row_bitmap):
    indices = []
    seat = 0
    while row_bitmap > 0:
        if row_bitmap & 1:
            indices.append(seat)
        row_bitmap >>= 1
        seat += 1
    return indices

def pack_badge_nibbles(nibbles):
    code = 0
    for i, val in enumerate(nibbles):
        code |= (val & 15) << (4 * i)
    return code

def count_common_permissions(user_masks):
