    return ((pattern << k) | (pattern >> (8 - k))) & 255

def highest_differing_bit(bitmap_a, bitmap_b):
    diff = bitmap_a ^ bitmap_b
    if diff == 0:
        return -1
    return diff.bit_length() - 1

def clear_lowest_k_tasks(queue_bitmap, k):
