def nth_ticket_code(a, b, k):
    if k == 0:
        return a
    if k == 1:
        return b
    prev2, prev1 = a, b
    for _ in range(2, k + 1):
        prev2, prev1 = prev1, abs(prev1 - prev2)
    return prev1

def auditorium_row_seats(n, first_row, add_a, add_b):
