def nth_beacon_interval(n, a, b, c):
    seq = [a, b, c]
    if n <= 3:
        return seq[n - 1]
    for _ in range(3, n):
        seq.append(seq[-1] + seq[-3])
    return seq[-1]

def generate_badge_serials(n, seed):
