    return True

def beacon_intervals(a, b, c, n):
    seq = [a, b, c]
    for _ in range(n - 3):
        seq.append(seq[-3] + seq[-1])
    return seq[:n]

def trace_packet_sizes(size, header, steps):
    trace = [size]
    for _ in range(steps):
        curr = trace[-1]
        if curr % 2 == 0:
            trace.append(curr // 2)
        else:
            trace.append(curr + header)
    return trace

def first_sharp_drop(readings, threshold):
    for i in range(1, len(readings)):
        if readings[i - 1] - readings[i] > threshold:
            return readings[i]
    return None

def find_adjacent_seats(chart):
    for r, row in enumerate(chart):
        for c in range(len(row) - 1):
            if row[c] == 0 and row[c + 1] == 0:
                return (r, c)
    return (-1, -1)

def last_shelf_with_prefix(labels, prefix):
    for i in range(len(labels) - 1, -1, -1):
        if labels[i].startswith(prefix):
            return i
    return -1

def closest_song_duration(playlist, target):
    best_title = playlist[0][0]
    best_diff = abs(playlist[0][1] - target)
    for title, duration in playlist[1:]:
        diff = abs(duration - target)
        if diff < best_diff:
            best_diff = diff
            best_title = title
    return best_title

def find_valid_tickets(tickets):
    result = []
    for code in tickets:
        if len(code) == 6 and code[-1] in '02468':
            result.append(code)
    return result

def first_overweight_package(weights, capacity):
    low, high = 0, len(weights) - 1
    ans = -1
    while low <= high:
        mid = (low + high) // 2
        if weights[mid] > capacity:
            ans = weights[mid]
            high = mid - 1
        else:
            low = mid + 1
    return ans

def find_recharge_stop(distances, battery_range):
    total = 0
    for idx, dist in enumerate(distances):
        total += dist
        if total > battery_range:
            return idx
    return -1

def first_available_item(order_items, warehouse_stock):
    stock_set = set(warehouse_stock)
    for item in order_items:
        if item in stock_set:
            return item
    return None

def find_three_day_dry_spell(rainfall):
    for i in range(len(rainfall) - 2):
        if rainfall[i] == 0 and rainfall[i + 1] == 0 and rainfall[i + 2] == 0:
            return i
    return -1

def find_uncomfortable_rooms(rooms, low, high):
    flagged = []
    for name, temp in rooms.items():
        if temp < low or temp > high:
            flagged.append(name)
    return sorted(flagged)

def is_shelf_symmetric(labels, target):
    left, right = 0, len(labels) - 1
    while left <= right:
        if labels[left] + labels[right] != target:
            return False
        left += 1
        right -= 1
    return True

def count_shared_timestamps(log_a, log_b):
    i = j = count = 0
    while i < len(log_a) and j < len(log_b):
        if log_a[i] == log_b[j]:
            count += 1
            i += 1
            j += 1
        elif log_a[i] < log_b[j]:
            i += 1
        else:
            j += 1
    return count

def count_shippable_pairs(weights, limit):
    left, right = 0, len(weights) - 1
    count = 0
    while left < right:
        if weights[left] + weights[right] <= limit:
            count += (right - left)
            left += 1
        else:
            right -= 1
    return count

def compress_temp_readings(readings):
    if not readings:
        return []
    result = [readings[0]]
    for i in range(1, len(readings)):
        if readings[i] != readings[i - 1]:
            result.append(readings[i])
    return result

def visited_all_checkpoints(route, checkpoints):
    i = j = 0
    while i < len(route) and j < len(checkpoints):
        if route[i] == checkpoints[j]:
            j += 1
        i += 1
    return j == len(checkpoints)

def alternate_end_seats(seats):
    left, right = 0, len(seats) - 1
    order = []
    while left <= right:
        order.append(seats[left])
        if left < right:
            order.append(seats[right])
        left += 1
        right -= 1
    return order

def match_boots_to_skis(boots, skis):
    i = j = matches = 0
    while i < len(boots) and j < len(skis):
        if abs(boots[i] - skis[j]) <= 1:
            matches += 1
            i += 1
            j += 1
        elif boots[i] < skis[j]:
            i += 1
        else:
            j += 1
    return matches

def trim_silence_frames(levels):
    left, right = 0, len(levels) - 1
    while left <= right and levels[left] == 0:
        left += 1
    while right >= left and levels[right] == 0:
        right -= 1
    return levels[left:right + 1]

def toggle_light_switches(mask, switches):
    for s in switches:
        mask ^= (1 << s)
    return mask

def count_occupied_seats(mask_a, mask_b):
    combined = mask_a | mask_b
    return bin(combined).count('1')

def lowest_active_alarm(status):
    if status == 0:
        return -1
    low_bit = status & -status
    return low_bit.bit_length() - 1

def filter_vip_tickets(tickets, bit_pos):
    flag = 1 << bit_pos
    return [t for t in tickets if (t & flag) != 0]

def clear_lowest_flags(flags, k):
    for _ in range(k):
        flags &= (flags - 1)
    return flags

def common_aisle_prefixes(inv_a, inv_b):
    aisles_a = {label.split('-')[0] for label in inv_a}
    aisles_b = {label.split('-')[0] for label in inv_b}
    return sorted(aisles_a & aisles_b)

def count_distinct_temperatures(readings):
    floored = {int(r) for r in readings}
    return len(floored)

def unique_duration_songs(playlist):
    seen_lengths = set()
    result = []
    for title, length in playlist:
        if length not in seen_lengths:
            seen_lengths.add(length)
            result.append(title)
    return result

def single_show_seats(morning_seats, evening_seats):
    diff = set(morning_seats) ^ set(evening_seats)
    return sorted(diff)

def missing_pantry_items(specials, pantry):
    needed = set()
    for recipe in specials:
        needed.update(recipe)
    return sorted(needed - set(pantry))

def multi_room_badges(scan_log):
    rooms_per_badge = {}
    for badge, room in scan_log:
        rooms_per_badge.setdefault(badge, set()).add(room)
    return sorted(b for b, rooms in rooms_per_badge.items() if len(rooms) > 1)

def count_connected_routes(routes, transfer_stops):
    transfers = set(transfer_stops)
    count = 0
    for route in routes:
        if set(route) & transfers:
            count += 1
    return count

def universal_coupons(histories):
    if not histories:
        return []
    common = set(histories[0])
    for h in histories[1:]:
        common &= set(h)
    return sorted(common)

def filter_post_hashtags(post_tags, blocked_tags):
    allowed = {t.lower() for t in post_tags} - {b.lower() for b in blocked_tags}
    return sorted(allowed)

def most_empty_row(seat_map):
    best_row = 0
    max_zeros = -1
    for i, row in enumerate(seat_map):
        zeros = row.count(0)
        if zeros > max_zeros:
            max_zeros = zeros
            best_row = i
    return best_row

def total_altitude_gain(altitudes):
    gain = 0
    for i in range(1, len(altitudes)):
        if altitudes[i] > altitudes[i - 1]:
            gain += altitudes[i] - altitudes[i - 1]
    return gain

def cumulative_restock_levels(changes):
    levels = []
    total = 0
    for c in changes:
        if c > 0:
            total += c
        levels.append(total)
    return levels

def common_attendees(room1, room2, room3):
    s1, s2, s3 = set(room1), set(room2), set(room3)
    overlap = (s1 & s2) | (s2 & s3) | (s1 & s3)
    return sorted(list(overlap))

def count_digit_heavy_skus(skus):
    count = 0
    for sku in skus:
        digits = sum(1 for c in sku if c.isdigit())
        letters = sum(1 for c in sku if c.isalpha())
        if digits > letters:
            count += 1
    return count

def avg_hashtags_per_post(captions):
    if not captions:
        return 0.0
    total_tags = 0
    for text in captions:
        total_tags += sum(1 for word in text.split() if word.startswith('#'))
    return round(total_tags / len(captions), 1)

def poem_line_word_spread(poem):
    if not poem.strip():
        return 0
    lines = poem.split('\n')
    counts = [len(line.split()) for line in lines]
    return max(counts) - min(counts)

def count_shouting_sentences(review):
    sentences = [s for s in review.split('.') if s.strip()]
    count = 0
    for s in sentences:
        words = s.split()
        if any(len(w) >= 2 and w.isupper() and w.isalpha() for w in words):
            count += 1
    return count

def aisle_label_lengths(labels):
    totals = {}
    for label in labels:
        if label:
            aisle = label[0].upper()
            totals[aisle] = totals.get(aisle, 0) + len(label)
    return totals

def chorus_vocabulary_density(chorus):
    words = [w.lower() for w in chorus.split()]
    if not words:
        return 0.0
    return round(len(set(words)) / len(words), 2)

def count_short_prefix_logs(logs):
    count = 0
    for log in logs:
        if ':' in log:
            prefix = log.split(':', 1)[0]
            if len(prefix) < 5:
                count += 1
    return count

def chat_punctuation_percentage(message):
    chars = [c for c in message if c != ' ']
    if not chars:
        return 0.0
    punct = sum(1 for c in chars if c in '!?.,')
    return round((punct / len(chars)) * 100, 1)

def mode_headline_word_length(headline):
    words = headline.split()
    if not words:
        return 0
    counts = {}
    for w in words:
        counts[len(w)] = counts.get(len(w), 0) + 1
    return min(counts.keys(), key=lambda k: (-counts[k], k))

def rows_with_consecutive_empty_seats(seat_map, k):
    target = '0' * k
    result = []
    for idx, row in enumerate(seat_map):
        row_str = ''.join(str(seat) for seat in row)
        if target in row_str:
            result.append(idx)
    return result

def sum_perimeter_stock(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    total = 0
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                total += grid[r][c]
    return total

def count_interior_heat_peaks(grid):
    count = 0
    for r in range(1, len(grid) - 1):
        for c in range(1, len(grid[0]) - 1):
            val = grid[r][c]
            if val > grid[r-1][c] and val > grid[r+1][c] and val > grid[r][c-1] and val > grid[r][c+1]:
                count += 1
    return count

def lightest_shelf_column(grid):
    col_Totals = [sum(grid[r][c] for r in range(len(grid))) for c in range(len(grid[0]))]
    min_weight = min(col_Totals)
    return col_Totals.index(min_weight)

def snake_scan_labels(grid):
    result = []
    for idx, row in enumerate(grid):
        if idx % 2 == 0:
            result.extend(row)
        else:
            result.extend(row[::-1])
    return result

def clean_panel_readings(grid):
    cleaned = []
    for row in grid:
        cleaned.append([val if val >= 0 else 0 for val in row])
    return cleaned

def diagonal_brightness_diff(matrix):
    n = len(matrix)
    main_sum = sum(matrix[i][i] for i in range(n))
    anti_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    return abs(main_sum - anti_sum)

def max_pool_image(matrix):
    pooled = []
    for r in range(0, len(matrix), 2):
        row = []
        for c in range(0, len(matrix[0]), 2):
            block_max = max(matrix[r][c], matrix[r][c+1], matrix[r+1][c], matrix[r+1][c+1])
            row.append(block_max)
        pooled.append(row)
    return pooled

def rotate_schedule_rows(grid, k):
    if not grid or not grid[0]:
        return grid
    cols = len(grid[0])
    shift = k % cols
    return [row[-shift:] + row[:-shift] if shift else row[:] for row in grid]

def count_level_adjacent_plots(grid):
    rows, cols = len(grid), len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            neighbors = []
            if r > 0: neighbors.append(grid[r-1][c])
            if r < rows - 1: neighbors.append(grid[r+1][c])
            if c > 0: neighbors.append(grid[r][c-1])
            if c < cols - 1: neighbors.append(grid[r][c+1])
            if grid[r][c] in neighbors:
                count += 1
    return count

def low_stock_shelves(inventory, threshold):
    result = []
    for shelf, title, stock in inventory:
        if stock < threshold:
            result.append(shelf)
    return result

def hottest_sensor(readings):
    best_id = readings[0][0]
    max_temp = readings[0][2]
    for sensor_id, timestamp, temp in readings:
        if temp > max_temp:
            max_temp = temp
            best_id = sensor_id
    return best_id

def swap_badge_names(badges):
    swapped = []
    for badge_id, first, last in badges:
        swapped.append((badge_id, last, first))
    return swapped

def count_free_seats(seats, target_row):
    count = 0
    for row, num, occupied in seats:
        if row == target_row and not occupied:
            count += 1
    return count

def apply_tag_discount(tags, percent):
    factor = 1 - (percent / 100.0)
    updated = []
    for code, price in tags:
        updated.append((code, round(price * factor, 2)))
    return updated

def weight_by_zone(parcels):
    totals = {}
    for tracking_id, zone, weight in parcels:
        totals[zone] = totals.get(zone, 0) + weight
    return totals

def delayed_flights(flights):
    delays = []
    for code, sched, actual in flights:
        if actual > sched:
            delays.append((code, actual - sched))
    return delays

def merge_roster_grades(roster, grades):
    grade_map = {sid: grade for sid, grade in grades}
    merged = []
    for sid, name in roster:
        if sid in grade_map:
            merged.append((sid, name, grade_map[sid]))
    return merged

def long_tracks(playlist, min_minutes):
    threshold = min_minutes * 60
    result = []
    for title, artist, seconds in playlist:
        if seconds > threshold:
            result.append(title)
    return result

def zone_temp_spreads(readings):
    spreads = []
    for zone, min_t, max_t in readings:
        spreads.append((zone, max_t - min_t))
    return spreads

def total_parcel_weight(items):
    total = 0
    for name, count, weight in items:
        total += count * weight
    return total

def cheapest_open_seat(seats):
    open_seats = [s for s in seats if s[2]]
    if not open_seats:
        return None
    best = min(open_seats, key=lambda s: s[1])
    return best[0]

def flip_receipt_ends(receipts):
    flipped = []
    for cashier, amount, register in receipts:
        flipped.append((register, amount, cashier))
    return flipped

def tally_by_category(stock):
    totals = {}
    for sku, category, qty in stock:
        totals[category] = totals.get(category, 0) + qty
    return totals

def filter_full_shifts(shifts, min_hours):
    kept = []
    for badge, start, end in shifts:
        if end - start >= min_hours:
            kept.append((badge, start, end))
    return kept

def count_late_trains(arrivals, grace_minutes):
    late = 0
    for train, sched, actual in arrivals:
        if actual - sched > grace_minutes:
            late += 1
    return late

def extract_sensor_temps(log_line):
    temps = []
    for entry in log_line.split():
        _, val = entry.split('=')
        if val != 'ERR':
            temps.append(float(val))
    return temps

def count_section_tickets(tickets):
    counts = {}
    for ticket in tickets:
        section = ticket.split('/')[0]
        counts[section] = counts.get(section, 0) + 1
    return counts

def parse_recipe_amounts(recipe_str):
    if not recipe_str:
        return {}
    ingredients = {}
    for item in recipe_str.split(';'):
        amount, _, name = item.strip().split(' ', 2)
        ingredients[name] = int(amount)
    return ingredients

def calculate_box_volume(dim_str):
    clean_str = dim_str[:-2]
    l, w, h = clean_str.split('x')
    return int(l) * int(w) * int(h)

def compute_net_balance(transactions):
    balance = 0.0
    for tx in transactions:
        amount_str = tx.split(':')[0]
        balance += float(amount_str)
    return round(balance, 2)

def calculate_chess_score(matches, player):
    score = 0.0
    for match in matches:
        pair, result = match.split(':')
        players = pair.split('-')
        if player in players:
            if result == player:
                score += 1.0
            elif result == 'DRAW':
                score += 0.5
    return score

def filter_packages_by_major(packages, min_major):
    valid = []
    for pkg in packages:
        name, version = pkg.split('@')
        major = int(version.split('.')[0])
        if major >= min_major:
            valid.append(name)
    return valid

def count_shelf_codes(alphabet_size):
    if alphabet_size < 2:
        return 0
    return alphabet_size * (alphabet_size - 1) * (alphabet_size - 1)

def count_valid_meals(starters, mains, desserts, limit):
    ways = 0
    for s in starters:
        for m in mains:
            for d in desserts:
                if s + m + d <= limit:
                    ways += 1
    return ways

def ways_to_place_two(row):
    empty = row.count(0)
    return empty * (empty - 1) // 2

def generate_badge_prefixes(dept, branch):
    prefixes = []
    for d in dept:
        for b in branch:
            if d != b:
                prefixes.append(d + b)
    return prefixes

def count_rising_playlists(lengths):
    n = len(lengths)
    count = 0
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if lengths[i] < lengths[j] < lengths[k]:
                    count += 1
    return count

def count_balanced_triplets(readings):
    n = len(readings)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                t = sorted([readings[i], readings[j], readings[k]])
                if t[0] + t[2] == 2 * t[1]:
                    count += 1
    return count

def count_even_splits(n):
    if n < 2:
        return 0
    k = n // 2
    ways = 1
    for i in range(1, k + 1):
        ways = ways * (n - i + 1) // i
    if n % 2 == 0:
        ways //= 2
    return ways

def count_symmetric_sum_pins(digits):
    count = 0
    for a in digits:
        for b in digits:
            for c in digits:
                for d in digits:
                    if a + b == c + d:
                        count += 1
    return count

def count_shift_schedules(morning, afternoon):
    m = len(morning)
    count = 0
    for i in range(m):
        for j in range(i + 1, m):
            if morning[i][1] <= morning[j][0] or morning[j][1] <= morning[i][0]:
                end_m = max(morning[i][1], morning[j][1])
                for a in afternoon:
                    if a[0] >= end_m:
                        count += 1
    return count

def exclusive_aisles(log1, log2):
    aisles1 = {code.split('-')[0] for code in log1}
    aisles2 = {code.split('-')[0] for code in log2}
    return sorted(aisles1 - aisles2)

def has_unique_ticket_suffixes(tickets):
    suffixes = {t[-3:] for t in tickets}
    return len(suffixes) == len(tickets)

def count_distinct_degrees(readings):
    distinct = {int(r) for r in readings}
    return len(distinct)

def shared_playlist_durations(playlists):
    if not playlists:
        return []
    common = set(playlists[0])
    for pl in playlists[1:]:
        common &= set(pl)
    return sorted(common)

def single_session_seats(morning, afternoon):
    diff = set(morning) ^ set(afternoon)
    return sorted(diff)

def first_order_per_table(orders):
    seen_tables = set()
    result = []
    for table, dish in orders:
        if table not in seen_tables:
            seen_tables.add(table)
            result.append((table, dish))
    return result

def repeated_badge_scans(scans):
    seen = set()
    repeated = set()
    for badge in scans:
        if badge in seen:
            repeated.add(badge)
        seen.add(badge)
    return sorted(repeated)

def count_unique_ingredients(recipes):
    all_ingredients = set()
    for items in recipes.values():
        all_ingredients.update(items)
    return len(all_ingredients)

def free_radio_channels(start_ch, end_ch, occupied):
    all_channels = set(range(start_ch, end_ch + 1))
    return sorted(all_channels - set(occupied))

def exclusive_shelf_labels(inv1, inv2):
    set1 = set(inv1)
    set2 = set(inv2)
    return sorted(list(set1 ^ set2))

def has_duplicate_tickets(tickets):
    seen = set()
    for t in tickets:
        low = t.lower()
        if low in seen:
            return True
        seen.add(low)
    return False

def count_unique_readings(daily_logs):
    unique_degrees = set()
    for log in daily_logs:
        unique_degrees.update(log)
    return len(unique_degrees)

def deduplicate_durations(durations):
    seen = set()
    result = []
    for d in durations:
        if d not in seen:
            seen.add(d)
            result.append(d)
    return result

def consistently_booked_seats(performances):
    if not performances:
        return []
    common = set(performances[0])
    for perf in performances[1:]:
        common &= set(perf)
    return sorted(list(common))

def extract_unique_hashtags(captions):
    tags = set()
    for cap in captions:
        for word in cap.split():
            if word.startswith('#'):
                tags.add(word)
    return sorted(list(tags))

def count_missing_badges(required, scanned):
    req_set = set(required)
    scan_set = set(scanned)
    return len(req_set - scan_set)

def find_solo_courses(enrollments):
    counts = {}
    for courses in enrollments.values():
        for c in set(courses):
            counts[c] = counts.get(c, 0) + 1
    return sorted([c for c, cnt in counts.items() if cnt == 1])

def count_area_codes(phones):
    codes = set()
    for p in phones:
        codes.add(p.split('-')[0])
    return len(codes)

def first_track_reaching_target(durations, target):
    elapsed = 0
    for i, d in enumerate(durations):
        elapsed += d
        if elapsed >= target:
            return i
    return -1

def shelf_range_weights(weights, queries):
    prefix = [0]
    for w in weights:
        prefix.append(prefix[-1] + w)
    return [prefix[r + 1] - prefix[l] for l, r in queries]

def count_overcapacity_stops(deltas, capacity):
    passengers = 0
    over_count = 0
    for d in deltas:
        passengers += d
        if passengers > capacity:
            over_count += 1
    return over_count

def drone_altitude_bounds(changes):
    alt = 0
    low = 0
    high = 0
    for c in changes:
        alt += c
        if alt < low:
            low = alt
        if alt > high:
            high = alt
    return (high, low)

def equal_rainfall_split_day(rainfall):
    total = sum(rainfall)
    running = 0
    for i, r in enumerate(rainfall):
        running += r
        if running * 2 == total:
            return i
    return -1

def cumulative_defective_counts(tags):
    count = 0
    history = []
    for tag in tags:
        if tag == 'defective':
            count += 1
        history.append(count)
    return history

def fence_post_positions(gaps):
    positions = [0]
    for g in gaps:
        positions.append(positions[-1] + g)
    return positions

def count_covered_aisles(shelf_ranges):
    covered = set()
    for start, end in shelf_ranges:
        for aisle in range(start, end + 1):
            covered.add(aisle)
    return len(covered)

def broadcast_overlap_minutes(slot1, slot2):
    start = max(slot1[0], slot2[0])
    end = min(slot1[1], slot2[1])
    return max(0, end - start)

def find_out_of_range_temps(readings, min_temp, max_temp):
    result = []
    for temp in readings:
        if temp < min_temp or temp > max_temp:
            result.append(temp)
    return result

def format_seat_blocks(seats):
    if not seats:
        return []
    blocks = []
    start = prev = seats[0]
    for s in seats[1:]:
        if s == prev + 1:
            prev = s
        else:
            blocks.append(str(start) if start == prev else f"{start}-{prev}")
            start = prev = s
    blocks.append(str(start) if start == prev else f"{start}-{prev}")
    return blocks

def delivery_idle_gaps(windows):
    gaps = []
    for i in range(len(windows) - 1):
        gap = windows[i + 1][0] - windows[i][1]
        gaps.append(max(0, gap))
    return gaps

def can_book_campsite(stay, openings):
    req_start, req_end = stay
    for open_start, open_end in openings:
        if open_start <= req_start and req_end <= open_end:
            return True
    return False

def common_drone_altitude(fleet_ranges):
    if not fleet_ranges:
        return None
    low = max(r[0] for r in fleet_ranges)
    high = min(r[1] for r in fleet_ranges)
    return (low, high) if low <= high else None

def clip_audio_segments(segments, min_time, max_time):
    clipped = []
    for start, end in segments:
        s = max(min_time, start)
        e = min(max_time, end)
        if s < e:
            clipped.append((s, e))
    return clipped

def longest_exhibition_span(exhibitions):
    best = exhibitions[0]
    for start, end in exhibitions:
        if (end - start + 1) > (best[1] - best[0] + 1):
            best = (start, end)
    return best

def toggle_seat_reservations(row_mask, seats):
