def acknowledge_lowest_fault(register):
    if register == 0:
        return 0
    return register & (register - 1)

def filter_qualified_badges(badges, required_mask):
    qualified = []
    for b in badges:
        if (b & required_mask) == required_mask:
            qualified.append(b)
    return qualified

def decode_work_days(schedule_mask):
    days = []
    for day in range(7):
        if (schedule_mask >> day) & 1:
            days.append(day)
    return days

def fit_crates_on_pallet(W, H, w, h):
    if w <= 0 or h <= 0:
        return 0
    cols = W // w
    rows = H // h
    return cols * rows

def count_pool_border_tiles(L, W):
    if L == 1 or W == 1:
        return L * W
    return 2 * L + 2 * W - 4

def rug_overlap_area(rug1, rug2):
    x_left = max(rug1[0], rug2[0])
    y_bottom = max(rug1[1], rug2[1])
    x_right = min(rug1[2], rug2[2])
    y_top = min(rug1[3], rug2[3])
    if x_right <= x_left or y_top <= y_bottom:
        return 0
    return (x_right - x_left) * (y_top - y_bottom)

def count_sensors_in_radar(sensors, cx, cy, r):
    count = 0
    r_sq = r * r
    for x, y in sensors:
        if (x - cx) ** 2 + (y - cy) ** 2 <= r_sq:
            count += 1
    return count

def are_towers_collinear(t1, t2, t3):
    x1, y1 = t1
    x2, y2 = t2
    x3, y3 = t3
    return (y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1)

def stacked_cubes_exposed_area(sides):
    if not sides:
        return 0
    top_area = sides[0] ** 2
    side_area = sum(4 * (s ** 2) for s in sides)
    return top_area + side_area

def l_shaped_room_area(W, H, w, h):
    if w >= W or h >= H:
        return 0
    return (W * H) - (w * h)

def seat_coordinates(ticket_num, seats_per_row, d):
    idx = ticket_num - 1
    row = idx // seats_per_row
    col = idx % seats_per_row
    return (col, row * d)

def count_ticket_prefixes(tickets):
