def first_oversized_package(weights, limit):
    low, high = 0, len(weights) - 1
    ans = -1
    while low <= high:
        mid = (low + high) // 2
        if weights[mid] > limit:
            ans = weights[mid]
            high = mid - 1
        else:
            low = mid + 1
    return ans

def cheapest_vegan_item(menu):
