def compress_forecast(forecast):
    if not forecast:
        return ''
    chunks = []
    count = 1
    for i in range(1, len(forecast)):
        if forecast[i] == forecast[i - 1]:
            count += 1
        else:
            chunks.append(f'{count}{forecast[i - 1]}')
            count = 1
    chunks.append(f'{count}{forecast[-1]}')
    return '/'.join(chunks)

def count_books_by_aisle(labels):
