    for d in durations:
        prod *= d
    zeros = 0
    while prod > 0 and prod % base == 0:
        zeros += 1
        prod //= base
    return zeros

def find_batch_multiplier(batch_size, container_size, target_rem):
    for m in range(1, container_size + 1):
        if (batch_size * m) % container_size == target_rem:
            return m
    return -1

import math

def check_adjacent_frequencies(freqs, threshold):
    for i in range(len(freqs) - 1):
        if math.gcd(freqs[i], freqs[i + 1]) <= threshold:
            return False
    return True

def generate_inventory_levels(start_stock, daily_sales, restock, n):
    if n <= 0:
        return []
    levels = [start_stock]
    for day in range(2, n + 1):
        current = levels[-1] - daily_sales
        if day % 3 == 0:
            current += restock
        levels.append(current)
    return levels

def nth_beacon_pulse(p0, p1, n):
    if n == 0:
        return p0
    if n == 1:
        return p1
    prev2, prev1 = p0, p1
    for _ in range(2, n + 1):
        prev2, prev1 = prev1, 2 * prev1 - prev2
    return prev1

def smooth_thermometer_readings(readings):
    if not readings:
        return []
    smoothed = [readings[0]]
    for r in readings[1:]:
        smoothed.append((r + smoothed[-1]) // 2)
    return smoothed

def build_playlist_durations(first_track, up_step, down_step, n):
    if n <= 0:
        return []
    playlist = [first_track]
    for i in range(1, n):
        if i % 2 == 1:
            playlist.append(playlist[-1] + up_step)
        else:
            playlist.append(playlist[-1] - down_step)
    return playlist

def is_valid_shelf_sequence(capacities, overlap):
    for i in range(2, len(capacities)):
        if capacities[i] != capacities[i - 1] + capacities[i - 2] - overlap:
            return False
    return True

def generate_crate_weights(w0, w1, w2, n):
    weights = [w0, w1, w2]
    if n <= 3:
        return weights[:n]
    for _ in range(3, n):
        weights.append(weights[-1] + weights[-3])
    return weights

def count_covered_shelves(ranges):
    covered = set()
    for start, end in ranges:
        for shelf in range(start, end + 1):
            covered.add(shelf)
    return len(covered)

def total_quiet_time(broadcasts):
    quiet = 0
    for i in range(1, len(broadcasts)):
        gap = broadcasts[i][0] - broadcasts[i - 1][1]
        if gap > 0:
            quiet += gap
    return quiet

def filter_strict_tickets(tickets, barrier):
    low, high = barrier
    return [t for t in tickets if low < t < high]

def common_comfort_range(ranges):
    if not ranges:
        return None
    low = max(r[0] for r in ranges)
    high = min(r[1] for r in ranges)
    return (low, high) if low <= high else None

def format_seat_ranges(seats):
    if not seats:
        return []
    res = []
    start = prev = seats[0]
    for s in seats[1:]:
        if s == prev + 1:
            prev = s
        else:
            res.append(str(start) if start == prev else f"{start}-{prev}")
            start = prev = s
    res.append(str(start) if start == prev else f"{start}-{prev}")
    return res

def has_maintenance_conflict(window, bookings):
    w_start, w_end = window
    for b_start, b_end in bookings:
        if max(w_start, b_start) < min(w_end, b_end):
            return True
    return False

def widest_badge_range(ranges):
    best = ranges[0]
    max_count = best[1] - best[0] + 1
    for r in ranges[1:]:
        count = r[1] - r[0] + 1
        if count > max_count:
            max_count = count
            best = r
    return best

def count_weekday_in_month(num_days, start_day, target_day):
    count = 0
    for d in range(num_days):
        if (start_day + d) % 7 == target_day:
            count += 1
    return count

def day_of_year_to_month_day(day_num, month_lengths):
    for i, length in enumerate(month_lengths):
        if day_num <= length:
            return (i + 1, day_num)
        day_num -= length
    return (-1, -1)

def avg_uppercase_per_ticket(tickets):
    if not tickets:
        return 0.0
    total_upper = sum(1 for ticket in tickets for char in ticket if char.isupper())
    return round(total_upper / len(tickets), 2)

def count_digit_heavy_labels(labels):
    count = 0
    for label in labels:
        digits = sum(1 for c in label if c.isdigit())
        letters = sum(1 for c in label if c.isalpha())
        if digits > letters:
            count += 1
    return count

def title_length_spread(playlist):
    if not playlist:
        return 0
    lengths = [len(title) for title in playlist]
    return max(lengths) - min(lengths)

def hyphenated_token_percentage(log_line):
    tokens = log_line.split()
    if not tokens:
        return 0.0
    hyphen_count = sum(1 for t in tokens if '-' in t)
    return round((hyphen_count / len(tokens)) * 100.0, 1)

def sentence_word_counts(review):
    segments = review.split('.')
    counts = []
    for seg in segments:
        words = seg.split()
        if words:
            counts.append(len(words))
    return counts

def seat_occupancy_ratio(seat_map):
    occupied = seat_map.count('X')
    empty = seat_map.count('O')
    total = occupied + empty
    if total == 0:
        return 0.0
    return round(occupied / total, 3)

def count_numbered_steps(recipe_text):
    count = 0
    for line in recipe_text.splitlines():
        stripped = line.lstrip()
        if stripped and stripped[0].isdigit():
            count += 1
    return count

def most_common_word_length(message):
    words = message.split()
    if not words:
        return 0
    counts = {}
    for w in words:
        counts[len(w)] = counts.get(len(w), 0) + 1
    return min(counts.keys(), key=lambda k: (-counts[k], k))

def count_feedback_punctuation(feedbacks):
    targets = {'.', ',', '!', '?'}
    return sum(1 for msg in feedbacks for ch in msg if ch in targets)

def serial_character_diversity(serial):
    if not serial:
        return 0.0
    return round(len(set(serial)) / len(serial), 2)

def max_playlist_songs(durations, max_time):
    count = 0
    for d in sorted(durations):
        if max_time >= d:
            max_time -= d
            count += 1
        else:
            break
    return count

def min_shelf_labels(label_widths, target_length):
    covered = 0
    count = 0
    for w in sorted(label_widths, reverse=True):
        if covered >= target_length:
            break
        covered += w
        count += 1
    return count if covered >= target_length else -1

def match_shuttle_groups(groups, vans):
    groups = sorted(groups)
    vans = sorted(vans)
    g = 0
    for v in vans:
        if g < len(groups) and v >= groups[g]:
            g += 1
    return g

def max_stage_rehearsals(slots):
    count = 0
    last_end = -1
    for start, end in sorted(slots, key=lambda x: x[1]):
        if start >= last_end:
            count += 1
            last_end = end
    return count

def place_spaced_guests(seat_map):
    seats = list(seat_map)
    added = 0
    for i in range(len(seats)):
        left_ok = (i == 0 or seats[i - 1] == 0)
        right_ok = (i == len(seats) - 1 or seats[i + 1] == 0)
        if seats[i] == 0 and left_ok and right_ok:
            seats[i] = 1
            added += 1
    return added

def greedy_ascending_ticket(code):
    kept = [code[0]]
    for ch in code[1:]:
        if ch >= kept[-1]:
            kept.append(ch)
    return int(''.join(kept))

def theater_row_seats(s, n):
    if n <= 0:
        return []
    rows = [s]
    for k in range(2, n + 1):
        step = 4 if k % 2 == 0 else 2
        rows.append(rows[-1] + step)
    return rows

def scooter_battery_levels(drains):
    level = 100
    levels = []
    for d in drains:
        level -= d
        levels.append(level)
        if level < 30:
            level = 100
    return levels

def sort_playlist_times(times):
    def to_seconds(t):
        m, s = t.split(':')
        return int(m) * 60 + int(s)
    return sorted(times, key=to_seconds)

def sort_seat_codes(seats):
    def seat_key(seat):
        row = int(seat[:-1])
        col = seat[-1]
        return (row, -ord(col))
    return sorted(seats, key=seat_key)

def sort_recipe_steps(steps):
    def step_num(s):
        header = s.split(':')[0]
        return int(header.split()[1])
    return sorted(steps, key=step_num)

def max_pallets_in_zone(w, l, s):
    if s <= 0:
        return 0
    pallets_along_w = w // s
    pallets_along_l = l // s
    return pallets_along_w * pallets_along_l

def count_sensors_in_range(sensors, cx, cy, r):
    count = 0
    r_squared = r * r
    for x, y in sensors:
        if (x - cx) ** 2 + (y - cy) ** 2 <= r_squared:
            count += 1
    return count

def stage_light_bounding_area(lights):
    if not lights:
        return 0
    xs = [p[0] for p in lights]
    ys = [p[1] for p in lights]
    return (max(xs) - min(xs)) * (max(ys) - min(ys))

def garden_border_stones(w, l, t):
    outer_w = w + 2 * t
    outer_l = l + 2 * t
    return (outer_w * outer_l) - (w * l)

def window_overlap_area(win1, win2):
    x_left = max(win1[0], win2[0])
    y_bottom = max(win1[1], win2[1])
    x_right = min(win1[2], win2[2])
    y_top = min(win1[3], win2[3])
    if x_right > x_left and y_top > y_bottom:
        return (x_right - x_left) * (y_top - y_bottom)
    return 0

def rotate_sprite_clockwise(x, y, px, py):
    dx = x - px
    dy = y - py
    new_x = px + dy
    new_y = py - dx
    return (new_x, new_y)

def paintable_wall_area(w, h, windows):
    total = w * h
    for win_w, win_h in windows:
        total -= win_w * win_h
    return max(0, total)

def seats_near_vent(r, c, vr, vc, d):
    min_row = max(0, vr - d)
    max_row = min(r - 1, vr + d)
    min_col = max(0, vc - d)
    max_col = min(c - 1, vc + d)
    if max_row < min_row or max_col < min_col:
        return 0
    return (max_row - min_row + 1) * (max_col - min_col + 1)

def count_safe_readings(readings, ranges):
    count = 0
    for r in readings:
        if any(low <= r <= high for low, high in ranges):
            count += 1
    return count

def format_aisle_ranges(aisles):
    if not aisles:
        return []
    res, start, end = [], aisles[0], aisles[0]
    for a in aisles[1:]:
        if a == end + 1:
            end = a
        else:
            res.append(f"{start}-{end}" if start != end else str(start))
            start = end = a
    res.append(f"{start}-{end}" if start != end else str(start))
    return res

def delivery_gap_durations(windows):
    gaps = []
    for i in range(len(windows) - 1):
        gap = windows[i + 1][0] - windows[i][1]
        if gap > 0:
            gaps.append(gap)
    return gaps

def classify_parcels(weights, brackets):
    result = []
    for w in weights:
        label = 'Unknown'
        for low, high, name in brackets:
            if low <= w <= high:
                label = name
                break
        result.append(label)
    return result

def clamp_workout_logs(logs, period):
    p_start, p_end = period
    clamped = []
    for start, end in logs:
        s, e = max(start, p_start), min(end, p_end)
        if s < e:
            clamped.append((s, e))
    return clamped

def are_tickets_valid(tickets, blacklist):
    for t in tickets:
        for low, high in blacklist:
            if low <= t <= high:
                return False
    return True

def largest_shelf_range(shelves):
    best_id = None
    max_size = -1
    for shelf_id, start, end in shelves:
        size = end - start + 1
        if size > max_size:
            max_size = size
            best_id = shelf_id
    return best_id

def count_hallway_tiles(w, h, k):
    if k <= 0 or w < k or h < k:
        return 0
    cols = w // k
    rows = h // k
    return cols * rows

def zone_overlap_area(zone1, zone2):
    x_left = max(zone1[0], zone2[0])
    y_bottom = max(zone1[1], zone2[1])
    x_right = min(zone1[2], zone2[2])
    y_top = min(zone1[3], zone2[3])
    if x_right <= x_left or y_top <= y_bottom:
        return 0
    return (x_right - x_left) * (y_top - y_bottom)

def pad_bounding_area(pads):
    if not pads:
        return 0
    xs = [p[0] for p in pads]
    ys = [p[1] for p in pads]
    return (max(xs) - min(xs)) * (max(ys) - min(ys))

def count_fence_posts(x1, y1, x2, y2):
    width = abs(x2 - x1) + 1
    height = abs(y2 - y1) + 1
    if width == 1 or height == 1:
        return width * height
    return 2 * (width + height) - 4

def padded_label_perimeter(w, h, m):
    outer_w = w + 2 * m
    outer_h = h + 2 * m
    return 2 * (outer_w + outer_h)

def towers_are_collinear(t1, t2, t3):
    x1, y1 = t1
    x2, y2 = t2
    x3, y3 = t3
    return (y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1)

def surface_crate_count(w, d, h):
    total = w * d * h
    if w <= 2 or d <= 2 or h <= 2:
        return total
    inner = (w - 2) * (d - 2) * (h - 2)
    return total - inner

def count_shipment_boxes(weights, limit):
    left, right = 0, len(weights) - 1
    boxes = 0
    while left <= right:
        if weights[left] + weights[right] <= limit:
            left += 1
        right -= 1
        boxes += 1
    return boxes

def is_valid_station_code(code, route):
    i, j = 0, 0
    while i < len(code) and j < len(route):
        if code[i] == route[j]:
            i += 1
        j += 1
    return i == len(code)

def has_exact_commute_pair(durations, target):
    left, right = 0, len(durations) - 1
    while left < right:
        total = durations[left] + durations[right]
        if total == target:
            return True
        elif total < target:
            left += 1
        else:
            right -= 1
    return False

def reverse_shelf_letters(label):
    chars = list(label)
    left, right = 0, len(chars) - 1
    while left < right:
        if not chars[left].isalpha():
            left += 1
        elif not chars[right].isalpha():
            right -= 1
        else:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    return "".join(chars)

def interleave_ticket_prices(prices):
    left, right = 0, len(prices) - 1
    res = []
    while left <= right:
        res.append(prices[left])
        left += 1
        if left <= right:
            res.append(prices[right])
            right -= 1
    return res

def match_shirt_sizes(customers, shirts):
    i, j = 0, 0
    matched = 0
    while i < len(customers) and j < len(shirts):
        if shirts[j] >= customers[i]:
            matched += 1
            i += 1
        j += 1
    return matched

def is_ribbon_symmetric(ribbon):
    left, right = 0, len(ribbon) - 1
    while left <= right:
        if ribbon[left] != ribbon[right].upper() or not ribbon[right].islower():
            return False
        left += 1
        right -= 1
    return True

def sort_athlete_scores(records):
    def score_key(rec):
        name, s1, s2, s3 = rec
        top_two_sum = s1 + s2 + s3 - min(s1, s2, s3)
        return (-top_two_sum, name)
    return sorted(records, key=score_key)

def match_ticket_pattern(code, pattern):
    i = j = 0
    while i < len(code) and j < len(pattern):
        if pattern[j].isdigit():
            i += int(pattern[j])
            j += 1
        elif code[i] == pattern[j]:
            i += 1
            j += 1
        else:
            return False
    return i == len(code) and j == len(pattern)

def longest_valid_streak(readings):
    left = zeros = best = 0
    for right in range(len(readings)):
        if readings[right] == 0:
            zeros += 1
        while zeros > 1:
            if readings[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

def alternate_shelf_prices(prices):
    left, right = 0, len(prices) - 1
    result = []
    while left <= right:
        result.append(prices[left])
        left += 1
        if left <= right:
            result.append(prices[right])
            right -= 1
    return result

def count_close_arrivals(morning, evening, window):
    i = j = pairs = 0
    while i < len(morning) and j < len(evening):
        if abs(morning[i] - evening[j]) <= window:
            pairs += 1
            i += 1
            j += 1
        elif morning[i] < evening[j]:
            i += 1
        else:
            j += 1
    return pairs

def reverse_label_digits(label):
    chars = list(label)
    left, right = 0, len(chars) - 1
    while left < right:
        if not chars[left].isdigit():
            left += 1
        elif not chars[right].isdigit():
            right -= 1
        else:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    return ''.join(chars)

def space_out_badges(badges, min_gap):
    if not badges:
        return []
    kept = [badges[0]]
    for i in range(1, len(badges)):
        if badges[i] - kept[-1] >= min_gap:
            kept.append(badges[i])
    return kept

def min_server_pair_cost(front, back, target):
    i, j = 0, len(back) - 1
    best = -1
    while i < len(front) and j >= 0:
        total = front[i] + back[j]
        if total >= target:
            if best == -1 or total < best:
                best = total
            j -= 1
        else:
            i += 1
    return best

def group_tracks_into_albums(tracks, max_duration):
    albums = []
    current = []
    current_time = 0
    for t in tracks:
        if current and current_time + t > max_duration:
            albums.append(current)
            current = [t]
            current_time = t
        else:
            current.append(t)
            current_time += t
    if current:
        albums.append(current)
    return albums

def find_empty_seats(seat_map):
    empty = []
    for r_idx, row in enumerate(seat_map):
        for c_idx, seat in enumerate(row):
            if seat == 0:
                empty.append((r_idx, c_idx))
    return empty

def extract_shelf_numbers(labels):
    shelves = set()
    for label in labels:
        parts = label.split('-')
        if len(parts) == 2:
            shelves.add(int(parts[1]))
    return sorted(list(shelves))

def find_depleted_products(logs):
    totals = {}
    order = []
    for prod_id, change in logs:
        if prod_id not in totals:
            totals[prod_id] = 0
            order.append(prod_id)
        totals[prod_id] += change
    return [pid for pid in order if totals[pid] < 0]

def count_direction_reversals(coords):
    reversals = 0
    last_dir = 0
    for i in range(1, len(coords)):
        diff = coords[i] - coords[i - 1]
        if diff != 0:
            curr_dir = 1 if diff > 0 else -1
            if last_dir != 0 and curr_dir != last_dir:
                reversals += 1
            last_dir = curr_dir
    return reversals

def rotate_active_workers(workers, k, on_vacation):
    active = [w for w in workers if w not in on_vacation]
    if not active:
        return []
    k = k % len(active)
    return active[k:] + active[:k]

def sum_rain_gauge(measurements):
    total = 0
    for m in measurements:
        if m == 999:
            break
        if m > 0:
            total += m
    return total

def get_bay_number(label):
    parts = label.split('-')
    return int(parts[1])

def clean_ingredients(ingredients):
    cleaned = []
    for item in ingredients:
        cleaned.append(item.strip().lower())
    return cleaned

def reverse_flight_route(route):
    origin, dest = route.split('->')
    return dest + '->' + origin

def make_course_code(title, number):
    words = title.split()
    initials = ''.join(w[0].upper() for w in words)
    return initials + str(number)

def get_original_extension(filename):
    if filename.endswith('.bak'):
        filename = filename[:-4]
    parts = filename.split('.')
    return parts[-1]
